		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
		sample_type_id UUID NOT NULL,
		accepts BOOLEAN NOT NULL DEFAULT true,
		UNIQUE(location_id, sample_type_id)
	);

	CREATE TABLE IF NOT EXISTS connections (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		from_location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
		to_location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE,
		travel_minutes INT NOT NULL DEFAULT 30,
		cost_units DOUBLE PRECISION NOT NULL DEFAULT 1.0,
		cooled BOOLEAN NOT NULL DEFAULT false,
		active BOOLEAN NOT NULL DEFAULT true,
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS connection_capacity (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		connection_id UUID NOT NULL REFERENCES connections(id) ON DELETE CASCADE,
		capacity_units INT NOT NULL DEFAULT 0,
		reserved_units INT NOT NULL DEFAULT 0,
		cooled_capacity_units INT NOT NULL DEFAULT 0,
		cooled_reserved_units INT NOT NULL DEFAULT 0,
		UNIQUE(connection_id)
	);

	CREATE TABLE IF NOT EXISTS sample_types (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		name VARCHAR(255) NOT NULL,
		qualified_collector_required BOOLEAN NOT NULL DEFAULT false,
		required_qualification VARCHAR(64) NOT NULL DEFAULT '',
		container_type VARCHAR(255) NOT NULL DEFAULT 'standard',
		temperature_min_c DOUBLE PRECISION NOT NULL DEFAULT 2.0,
		temperature_max_c DOUBLE PRECISION NOT NULL DEFAULT 8.0,
		requires_cooled_route BOOLEAN NOT NULL DEFAULT false,
		batching_allowed BOOLEAN NOT NULL DEFAULT true,
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS sample_type_incompatibilities (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		sample_type_id UUID NOT NULL REFERENCES sample_types(id) ON DELETE CASCADE,
		incompatible_type_id UUID NOT NULL REFERENCES sample_types(id) ON DELETE CASCADE,
		UNIQUE(sample_type_id, incompatible_type_id)
	);

	CREATE TABLE IF NOT EXISTS requests (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		requester_id UUID NOT NULL REFERENCES users(id),
		origin_lat DOUBLE PRECISION NOT NULL,
		origin_lon DOUBLE PRECISION NOT NULL,
		origin_type VARCHAR(32) NOT NULL DEFAULT 'home',
		origin_node_id UUID REFERENCES locations(id),
		sample_type_id UUID NOT NULL REFERENCES sample_types(id),
		earliest_collection_at TIMESTAMPTZ NOT NULL,
		latest_collection_at TIMESTAMPTZ NOT NULL,
		delivery_deadline TIMESTAMPTZ NOT NULL,
		requested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		status VARCHAR(32) NOT NULL DEFAULT 'pending',
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS samples (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		request_id UUID REFERENCES requests(id),
		sample_type_id UUID NOT NULL REFERENCES sample_types(id),
		container_type VARCHAR(255) NOT NULL DEFAULT 'standard',
		temperature_min_c DOUBLE PRECISION NOT NULL DEFAULT 2.0,
		temperature_max_c DOUBLE PRECISION NOT NULL DEFAULT 8.0,
		status VARCHAR(32) NOT NULL DEFAULT 'requested',
		sealed BOOLEAN NOT NULL DEFAULT false,
		current_holder_id UUID REFERENCES users(id),
		origin_lat DOUBLE PRECISION NOT NULL,
		origin_lon DOUBLE PRECISION NOT NULL,
		origin_type VARCHAR(32) NOT NULL DEFAULT 'home',
		delivery_deadline TIMESTAMPTZ NOT NULL,
		serviceability VARCHAR(32) NOT NULL DEFAULT 'unserviceable',
		target_laboratory_id UUID REFERENCES locations(id),
		latest_lat DOUBLE PRECISION,
		latest_lon DOUBLE PRECISION,
		location_recorded_at TIMESTAMPTZ,
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS sample_exceptions (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		sample_id UUID NOT NULL REFERENCES samples(id) ON DELETE CASCADE,
		exception_type VARCHAR(64) NOT NULL,
		description TEXT NOT NULL DEFAULT '',
		recorded_by UUID REFERENCES users(id),
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS journeys (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		parent_journey_id UUID REFERENCES journeys(id),
		sample_ids JSONB NOT NULL DEFAULT '[]',
		plan_version INT NOT NULL DEFAULT 1,
		route_mode VARCHAR(32) NOT NULL DEFAULT 'direct',
		status VARCHAR(32) NOT NULL DEFAULT 'planned',
		valid BOOLEAN NOT NULL DEFAULT true,
		replan_status VARCHAR(32),
		estimated_delivery_at TIMESTAMPTZ,
		total_cost_units DOUBLE PRECISION DEFAULT 0.0,
		capacity_used INT DEFAULT 0,
		capacity_available INT DEFAULT 0,
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS journey_stops (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
		location_id UUID NOT NULL REFERENCES locations(id),
		stop_type VARCHAR(32) NOT NULL,
		sequence INT NOT NULL,
		estimated_at TIMESTAMPTZ NOT NULL,
		dwell_minutes INT DEFAULT 0,
		completed_at TIMESTAMPTZ,
		UNIQUE(journey_id, sequence)
	);

	CREATE TABLE IF NOT EXISTS journey_legs (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		journey_id UUID NOT NULL REFERENCES journeys(id) ON DELETE CASCADE,
		assignment_id UUID,
		sequence INT NOT NULL,
		status VARCHAR(32) NOT NULL DEFAULT 'pending',
		from_location_id UUID REFERENCES locations(id),
		to_location_id UUID REFERENCES locations(id),
		worker_id UUID REFERENCES users(id),
		sample_id UUID REFERENCES samples(id),
		UNIQUE(journey_id, sequence)
	);

	CREATE TABLE IF NOT EXISTS assignments (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		kind VARCHAR(32) NOT NULL,
		journey_id UUID REFERENCES journeys(id),
		sample_id UUID REFERENCES samples(id),
		worker_id UUID REFERENCES users(id),
		status VARCHAR(32) NOT NULL DEFAULT 'offered',
		from_location_id UUID REFERENCES locations(id),
		to_location_id UUID REFERENCES locations(id),
		node_id UUID REFERENCES locations(id),
		laboratory_id UUID REFERENCES locations(id),
		sequence INT DEFAULT 0,
		offer_expires_at TIMESTAMPTZ,
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS handoffs (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		sample_id UUID NOT NULL REFERENCES samples(id),
		journey_id UUID REFERENCES journeys(id),
		from_user_id UUID NOT NULL REFERENCES users(id),
		to_user_id UUID NOT NULL REFERENCES users(id),
		status VARCHAR(32) NOT NULL DEFAULT 'pending',
		sender_confirmed BOOLEAN NOT NULL DEFAULT false,
		receiver_confirmed BOOLEAN NOT NULL DEFAULT false,
		from_location_id UUID REFERENCES locations(id),
		to_location_id UUID REFERENCES locations(id),
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
		completed_at TIMESTAMPTZ
	);

	CREATE TABLE IF NOT EXISTS handling_checkpoints (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		sample_id UUID NOT NULL REFERENCES samples(id),
		recorded_by UUID NOT NULL REFERENCES users(id),
		container_type VARCHAR(255) NOT NULL,
		observed_temperature_c DOUBLE PRECISION NOT NULL,
		created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE TABLE IF NOT EXISTS audit_log (
		id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
		actor_id UUID NOT NULL,
		role VARCHAR(64) NOT NULL,
		actor_role VARCHAR(64) NOT NULL,
		action VARCHAR(128) NOT NULL,
		entity_type VARCHAR(64) NOT NULL,
		entity_id VARCHAR(64) NOT NULL,
		success BOOLEAN NOT NULL DEFAULT true,
		details JSONB NOT NULL DEFAULT '{}',
		occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
	);

	CREATE INDEX IF NOT EXISTS idx_audit_actor ON audit_log(actor_id);
	CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_log(entity_type, entity_id);
	CREATE INDEX IF NOT EXISTS idx_audit_occurred ON audit_log(occurred_at DESC);
	CREATE INDEX IF NOT EXISTS idx_audit_action ON audit_log(action);
	CREATE INDEX IF NOT EXISTS idx_samples_holder ON samples(current_holder_id);
	CREATE INDEX IF NOT EXISTS idx_samples_status ON samples(status);
	CREATE INDEX IF NOT EXISTS idx_assignments_worker ON assignments(worker_id);
	CREATE INDEX IF NOT EXISTS idx_assignments_status ON assignments(status);
	CREATE INDEX IF NOT EXISTS idx_journeys_status ON journeys(status);
	CREATE INDEX IF NOT EXISTS idx_sessions_token ON sessions(token);
	CREATE INDEX IF NOT EXISTS idx_user_roles_user ON user_roles(user_id);
	`

	_, err := d.Exec(schema)
	if err != nil {
		return fmt.Errorf("migrate: %w", err)
	}

	// Seed default sample types if none exist
	var count int
	d.QueryRow("SELECT COUNT(*) FROM sample_types").Scan(&count)
	if count == 0 {
		if err := d.seedSampleTypes(); err != nil {
			return fmt.Errorf("seed sample types: %w", err)
		}
	}

	log.Println("Migrations complete")
	return nil
}

func (d *DB) seedSampleTypes() error {
	types := []struct {
		name, container, qual string
		qualReq               bool
		minT, maxT             float64
		cooled                 bool
		batching               bool
	}{
		{"Amber", "standard", "Amber", true, 2.0, 8.0, false, true},
		{"Indigo", "standard", "Indigo", true, 2.0, 8.0, false, true},
		{"Frost", "cooled", "Frost", true, 2.0, 8.0, true, true},
		{"Pulse", "standard", "Pulse", true, 2.0, 8.0, false, false},
	}

	ids := make([]string, len(types))
	for i, t := range types {
		var id string
		err := d.QueryRow(
			`INSERT INTO sample_types (name, container_type, qualified_collector_required, required_qualification, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed)
			 VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING id`,
			t.name, t.container, t.qualReq, t.qual, t.minT, t.maxT, t.cooled, t.batching,
		).Scan(&id)
		if err != nil {
			return err
		}
		ids[i] = id
	}

	// Indigo incompatible with Amber (Amber=0, Indigo=1)
	_, err := d.Exec(`INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_type_id) VALUES ($1, $2)`, ids[1], ids[0])
	if err != nil {
		return err
	}
	_, err = d.Exec(`INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_type_id) VALUES ($1, $2)`, ids[0], ids[1])
	return err
}

func (d *DB) Reset() error {
	_, err := d.Exec(`
	DROP TABLE IF EXISTS handling_checkpoints CASCADE;
	DROP TABLE IF EXISTS handoffs CASCADE;
	DROP TABLE IF EXISTS assignments CASCADE;
	DROP TABLE IF EXISTS journey_legs CASCADE;
	DROP TABLE IF EXISTS journey_stops CASCADE;
	DROP TABLE IF EXISTS journeys CASCADE;
	DROP TABLE IF EXISTS sample_exceptions CASCADE;
	DROP TABLE IF EXISTS samples CASCADE;
	DROP TABLE IF EXISTS requests CASCADE;
	DROP TABLE IF EXISTS sample_type_incompatibilities CASCADE;
	DROP TABLE IF EXISTS sample_types CASCADE;
	DROP TABLE IF EXISTS connection_capacity CASCADE;
	DROP TABLE IF EXISTS connections CASCADE;
	DROP TABLE IF EXISTS laboratory_acceptance CASCADE;
	DROP TABLE IF EXISTS location_capacity CASCADE;
	DROP TABLE IF EXISTS user_assigned_locations CASCADE;
	DROP TABLE IF EXISTS user_active_role CASCADE;
	DROP TABLE IF EXISTS user_certifications CASCADE;
	DROP TABLE IF EXISTS user_roles CASCADE;
	DROP TABLE IF EXISTS sessions CASCADE;
	DROP TABLE IF EXISTS locations CASCADE;
	DROP TABLE IF EXISTS users CASCADE;
	DROP TABLE IF EXISTS audit_log CASCADE;
	`)
	if err != nil {
		return fmt.Errorf("drop: %w", err)
	}
	return d.RunMigrations()
}

