package auth

import (
	"crypto/rand"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"fmt"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

type AuthStore struct {
	DB *sql.DB
}

func New(db *sql.DB) *AuthStore {
	return &AuthStore{DB: db}
}

func (a *AuthStore) HashPassword(password string) (string, error) {
	bytes, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	return string(bytes), err
}

func (a *AuthStore) CheckPassword(hash, password string) bool {
	err := bcrypt.CompareHashAndPassword([]byte(hash), []byte(password))
	return err == nil
}

func GenerateToken() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}

func HashToken(token string) string {
	h := sha256.Sum256([]byte(token))
	return hex.EncodeToString(h[:])
}

func (a *AuthStore) CreateSession(userID string) (string, error) {
	token, err := GenerateToken()
	if err != nil {
		return "", err
	}
	hashed := HashToken(token)
	_, err = a.DB.Exec("INSERT INTO sessions (token, user_id) VALUES ($1, $2)", hashed, userID)
	if err != nil {
		return "", fmt.Errorf("create session: %w", err)
	}
	return token, nil
}

func (a *AuthStore) ValidateSession(token string) (string, string, string, error) {
	hashed := HashToken(token)
	var userID, username, activeRole sql.NullString
	err := a.DB.QueryRow(`
		SELECT u.id, u.username, uar.role
		FROM sessions s
		JOIN users u ON u.id = s.user_id
		LEFT JOIN user_active_role uar ON uar.user_id = u.id
		WHERE s.token = $1 AND u.active = true
	`, hashed).Scan(&userID, &username, &activeRole)
	if err != nil {
		return "", "", "", fmt.Errorf("invalid session")
	}
	return userID.String, username.String, activeRole.String, nil
}

func (a *AuthStore) DeleteSession(token string) error {
	hashed := HashToken(token)
	_, err := a.DB.Exec("DELETE FROM sessions WHERE token = $1", hashed)
	return err
}

func (a *AuthStore) GetUserRoles(userID string) ([]string, error) {
	rows, err := a.DB.Query("SELECT role FROM user_roles WHERE user_id = $1", userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var roles []string
	for rows.Next() {
		var r string
		if err := rows.Scan(&r); err != nil {
			return nil, err
		}
		roles = append(roles, r)
	}
	return roles, nil
}

func (a *AuthStore) HasRole(userID, role string) (bool, error) {
	var count int
	err := a.DB.QueryRow("SELECT COUNT(*) FROM user_roles WHERE user_id = $1 AND role = $2", userID, role).Scan(&count)
	return count > 0, err
}

func (a *AuthStore) GetActiveRole(userID string) (string, error) {
	var role sql.NullString
	err := a.DB.QueryRow("SELECT role FROM user_active_role WHERE user_id = $1", userID).Scan(&role)
	if err != nil {
		return "", err
	}
	if !role.Valid {
		return "", nil
	}
	return role.String, nil
}

func (a *AuthStore) SetActiveRole(userID, role string) error {
	_, err := a.DB.Exec(`
		INSERT INTO user_active_role (user_id, role) VALUES ($1, $2)
		ON CONFLICT (user_id) DO UPDATE SET role = $2
	`, userID, role)
	return err
}

func (a *AuthStore) EnsureAdmin(username, password string) error {
	var count int
	a.DB.QueryRow("SELECT COUNT(*) FROM users").Scan(&count)
	if count > 0 {
		return nil
	}
	hash, err := a.HashPassword(password)
	if err != nil {
		return err
	}
	var userID string
	err = a.DB.QueryRow(
		"INSERT INTO users (username, password_hash, full_name) VALUES ($1, $2, 'Administrator') RETURNING id",
		username, hash,
	).Scan(&userID)
	if err != nil {
		return err
	}
	// Admin gets all roles
	for _, role := range []string{"administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"} {
		_, err = a.DB.Exec("INSERT INTO user_roles (user_id, role) VALUES ($1, $2)", userID, role)
		if err != nil {
			return err
		}
	}
	_, err = a.DB.Exec("INSERT INTO user_active_role (user_id, role) VALUES ($1, 'administrator')", userID)
	return err
}

func ExtractTokenFromHeader(authHeader string) string {
	if strings.HasPrefix(authHeader, "Bearer ") {
		return authHeader[7:]
	}
	return ""
}

// Reap old sessions
func (a *AuthStore) ReapSessions() {
	a.DB.Exec("DELETE FROM sessions WHERE created_at < NOW() - INTERVAL '24 hours'")
}

func init() {
	// Start session reaper
	go func() {
		for {
			time.Sleep(time.Hour)
			// Reaper is started with db from main
		}
	}()
}

