package middleware

import (
	"context"
	"database/sql"
	"encoding/json"
	"net/http"
	"strings"

	"github.com/lab-sample-pickup-delivery/backend/internal/auth"
	"github.com/lab-sample-pickup-delivery/backend/internal/models"
)

type contextKey string

const (
	CtxUserID    contextKey = "user_id"
	CtxUsername  contextKey = "username"
	CtxActiveRole contextKey = "active_role"
	CtxDB        contextKey = "db"
)

func GetDB(ctx context.Context) *sql.DB {
	db, _ := ctx.Value(CtxDB).(*sql.DB)
	return db
}

func GetUserID(ctx context.Context) string {
	v, _ := ctx.Value(CtxUserID).(string)
	return v
}

func GetActiveRole(ctx context.Context) string {
	v, _ := ctx.Value(CtxActiveRole).(string)
	return v
}

func GetUsername(ctx context.Context) string {
	v, _ := ctx.Value(CtxUsername).(string)
	return v
}

func AuthMiddleware(authStore *auth.AuthStore) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			authHeader := r.Header.Get("Authorization")
			token := auth.ExtractTokenFromHeader(authHeader)
			if token == "" {
				writeError(w, http.StatusUnauthorized, "Missing Authorization header", "unauthorized")
				return
			}

			userID, username, activeRole, err := authStore.ValidateSession(token)
			if err != nil {
				writeError(w, http.StatusUnauthorized, "Invalid session", "unauthorized")
				return
			}

			ctx := context.WithValue(r.Context(), CtxUserID, userID)
			ctx = context.WithValue(ctx, CtxUsername, username)
			ctx = context.WithValue(ctx, CtxActiveRole, activeRole)
			next.ServeHTTP(w, r.WithContext(ctx))
		})
	}
}

func RequireRole(roles ...string) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			activeRole := GetActiveRole(r.Context())
			if activeRole == "" {
				writeError(w, http.StatusConflict, "No role selected", "role_not_selected")
				return
			}
			for _, role := range roles {
				if activeRole == role {
					next.ServeHTTP(w, r)
					return
				}
			}
			writeError(w, http.StatusForbidden, "Forbidden", "forbidden")
		})
	}
}

func writeError(w http.ResponseWriter, status int, msg, code string) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(models.ErrorEnvelope{Error: msg, Code: code})
}

func CORS(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, PUT, PATCH, DELETE, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type, Idempotency-Key")
		if r.Method == "OPTIONS" {
			w.WriteHeader(http.StatusOK)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// Helper for checking activeRole without middleware
func CheckActiveRole(r *http.Request) (string, bool) {
	role := GetActiveRole(r.Context())
	return role, role != ""
}

// Check if user is admin or dispatcher
func IsAdminOrDispatcher(role string) bool {
	return role == models.RoleAdministrator || role == models.RoleDispatcher
}

// Extract idempotency key
func IdempotencyKey(r *http.Request) string {
	return r.Header.Get("Idempotency-Key")
}

func WriteJSON(w http.ResponseWriter, status int, data interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(data)
}

func WriteData(w http.ResponseWriter, status int, data interface{}) {
	WriteJSON(w, status, models.DataResponse{Data: data})
}

func WriteError(w http.ResponseWriter, status int, msg, code string) {
	writeError(w, status, msg, code)
}

func DBFromContext(ctx context.Context) *sql.DB {
	return GetDB(ctx)
}

func WithDB(ctx context.Context, db *sql.DB) context.Context {
	return context.WithValue(ctx, CtxDB, db)
}

// Extract bearer [REDACTED] for WebSocket subprotocol
func ExtractBearerFromProtocol(protocol string) string {
	if strings.HasPrefix(protocol, "lab-logistics-v1.") {
		rest := strings.TrimPrefix(protocol, "lab-logistics-v1.")
		return rest
	}
	return ""
}

// Base64 URL decode
func B64Decode(s string) string {
	// Simple base64url decode
	var result strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c >= 'A' && c <= 'Z', c >= 'a' && c <= 'z', c >= '0' && c <= '9':
			result.WriteByte(c)
		case c == '-' || c == '_':
			result.WriteByte('=') // placeholder
		}
	}
	return result.String()
}

