		Active     bool   `json:"active"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	col := ""
	switch req.Function {
	case "collection_point":
		col = "collection_point"
	case "transfer_point":
		col = "transfer_point"
	case "hub":
		col = "hub"
	case "laboratory":
		col = "laboratory"
	default:
		middleware.WriteError(w, 400, "Invalid function", "invalid_json")
		return
	}

	h.DB.Exec(fmt.Sprintf(`UPDATE locations SET %s = $2, updated_at = NOW() WHERE id = $1`, col), req.LocationId, req.Active)
	middleware.WriteData(w, 200, map[string]interface{}{"locationId": req.LocationId, "function": req.Function, "active": req.Active})
}

