func (h *Handler) searchAuditTrail(w http.ResponseWriter, r *http.Request) {
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleDispatcher && activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		EntityType string `json:"entityType"`
		EntityId   string `json:"entityId"`
		ActorId    string `json:"actorId"`
		Action     string `json:"action"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}

	orderClause := "DESC"
	if req.Order == "oldest_first" {
		orderClause = "ASC"
	}

	query := "SELECT id, actor_id, role, actor_role, action, entity_type, entity_id, success, details, occurred_at FROM audit_log WHERE 1=1"
	countQuery := "SELECT COUNT(*) FROM audit_log WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if req.EntityType != "" {
		query += fmt.Sprintf(" AND entity_type = $%d", argIdx)
		countQuery += fmt.Sprintf(" AND entity_type = $%d", argIdx)
		args = append(args, req.EntityType)
		argIdx++
	}
	if req.EntityId != "" {
		query += fmt.Sprintf(" AND entity_id = $%d", argIdx)
		countQuery += fmt.Sprintf(" AND entity_id = $%d", argIdx)
		args = append(args, req.EntityId)
		argIdx++
	}
	if req.ActorId != "" {
		query += fmt.Sprintf(" AND actor_id = $%d", argIdx)
		countQuery += fmt.Sprintf(" AND actor_id = $%d", argIdx)
		args = append(args, req.ActorId)
		argIdx++
	}
	if req.Action != "" {
		query += fmt.Sprintf(" AND action = $%d", argIdx)
		countQuery += fmt.Sprintf(" AND action = $%d", argIdx)
		args = append(args, req.Action)
		argIdx++
	}

	var total int
	h.DB.QueryRow(countQuery, args...).Scan(&total)

	query += fmt.Sprintf(" ORDER BY occurred_at %s LIMIT $%d OFFSET $%d", orderClause, argIdx, argIdx+1)
	args = append(args, req.Limit, req.Offset)

	rows, err := h.DB.Query(query, args...)
	if err != nil {
		middleware.WriteError(w, 500, "Query error", "internal_error")
		return
	}
	defer rows.Close()

	entries := []models.AuditEntry{}
	for rows.Next() {
		var e models.AuditEntry
		var details string
		rows.Scan(&e.AuditId, &e.ActorId, &e.Role, &e.ActorRole, &e.Action, &e.EntityType, &e.EntityId, &e.Success, &details, &e.OccurredAt)
		json.Unmarshal([]byte(details), &e.Details)
		entries = append(entries, e)
	}

	hasMore := req.Offset+len(entries) < total
	nextOffset := req.Offset + req.Limit
	if !hasMore {
		nextOffset = 0
	}

	result := models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     req.Offset,
		Limit:      req.Limit,
		Order:      req.Order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	}

	middleware.WriteData(w, 200, result)
}

func (h *Handler) recordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		SampleId             string  `json:"sampleId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	// Verify user holds this sample
	var holderID sql.NullString
	h.DB.QueryRow(`SELECT current_holder_id FROM samples WHERE id = $1`, req.SampleId).Scan(&holderID)
	if holderID.String != userID {
		middleware.WriteError(w, 409, "You don't hold this sample", "custody_not_held")
		return
	}

	// Get sample temp range
	var tMin, tMax float64
	h.DB.QueryRow(`SELECT temperature_min_c, temperature_max_c FROM samples WHERE id = $1`, req.SampleId).Scan(&tMin, &tMax)

	var cpID string
	h.DB.QueryRow(`INSERT INTO handling_checkpoints (sample_id, recorded_by, container_type, observed_temperature_c) VALUES ($1, $2, $3, $4) RETURNING id`,
		req.SampleId, userID, req.ContainerType, req.ObservedTemperatureC).Scan(&cpID)

	// Check exception
	exception := false
	if req.ObservedTemperatureC < tMin || req.ObservedTemperatureC > tMax {
		exception = true
		h.DB.Exec(`INSERT INTO sample_exceptions (sample_id, exception_type, description, recorded_by) VALUES ($1, 'handling_noncompliant', 'Temperature out of range', $2)`, req.SampleId, userID)
	}

	h.audit(userID, activeRole, activeRole, "record_handling_checkpoint", "sample", req.SampleId, true, map[string]interface{}{
		"container": req.ContainerType,
		"temp":      req.ObservedTemperatureC,
		"exception": exception,
	})

	middleware.WriteData(w, 200, map[string]interface{}{
		"checkpointId":        cpID,
		"sampleId":            req.SampleId,
		"containerType":       req.ContainerType,
		"observedTemperatureC": req.ObservedTemperatureC,
		"exception":           exception,
	})
}

func (h *Handler) createUser(w http.ResponseWriter, r *http.Request) {
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		Username        string                   `json:"username"`
		Password        string                   `json:"password"`
		FullName        string                   `json:"fullName"`
		Roles           []string                 `json:"roles"`
		Qualifications  []string                 `json:"qualifications"`
		Certifications  []models.Certification   `json:"certifications"`
		AssignedLocationId string                `json:"assignedLocationId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	hashed, _ := h.AuthStore.HashPassword(req.Password)
	var userID string
	err := h.DB.QueryRow(`INSERT INTO users (username, password_hash, full_name) VALUES ($1, $2, $3) RETURNING id`,
		req.Username, hashed, req.FullName).Scan(&userID)
	if err != nil {
		middleware.WriteError(w, 409, "Username may exist", "concurrent_conflict")
		return
	}

	for _, role := range req.Roles {
		h.DB.Exec(`INSERT INTO user_roles (user_id, role) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, role)
	}

	for _, cert := range req.Certifications {
		var expires interface{} = nil
		if cert.ExpiresAt != nil {
			expires = *cert.ExpiresAt
		}
		h.DB.Exec(`INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1, $2, $3, $4) ON CONFLICT (user_id, code) DO UPDATE SET active = $3, expires_at = $4`, userID, cert.Code, cert.Active, expires)
	}

	if req.AssignedLocationId != "" {
		h.DB.Exec(`INSERT INTO user_assigned_locations (user_id, location_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, req.AssignedLocationId)
	}

	middleware.WriteData(w, 201, map[string]interface{}{
		"userId":   userID,
		"username": req.Username,
		"roles":    req.Roles,
		"active":   true,
	})
}

func (h *Handler) updateUserAccess(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		UserId              string                   `json:"userId"`
		Roles               []string                 `json:"roles"`
		Qualifications      []string                 `json:"qualifications"`
		Certifications      []models.Certification   `json:"certifications"`
		Active              bool                     `json:"active"`
		AssignedLocationId  string                   `json:"assignedLocationId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	h.DB.Exec(`UPDATE users SET active = $2, updated_at = NOW() WHERE id = $1`, req.UserId, req.Active)
	h.DB.Exec(`DELETE FROM user_roles WHERE user_id = $1`, req.UserId)
	for _, role := range req.Roles {
		h.DB.Exec(`INSERT INTO user_roles (user_id, role) VALUES ($1, $2)`, req.UserId, role)
	}

	h.DB.Exec(`DELETE FROM user_certifications WHERE user_id = $1`, req.UserId)
	for _, cert := range req.Certifications {
		var expires interface{} = nil
		if cert.ExpiresAt != nil {
			expires = *cert.ExpiresAt
		}
		h.DB.Exec(`INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1, $2, $3, $4)`, req.UserId, cert.Code, cert.Active, expires)
	}

	h.DB.Exec(`DELETE FROM user_assigned_locations WHERE user_id = $1`, req.UserId)
	if req.AssignedLocationId != "" {
		h.DB.Exec(`INSERT INTO user_assigned_locations (user_id, location_id) VALUES ($1, $2)`, req.UserId, req.AssignedLocationId)
	}

	h.audit(userID, activeRole, activeRole, "update_user_access", "user", req.UserId, true, nil)

	roles, _ := h.AuthStore.GetUserRoles(req.UserId)

	middleware.WriteData(w, 201, map[string]interface{}{
		"userId": req.UserId,
		"roles":  roles,
		"active": req.Active,
	})
}

func (h *Handler) createLocation(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		Name             string           `json:"name"`
		Coordinate       models.Coordinate `json:"coordinate"`
		CoverageKm       float64          `json:"coverageKm"`
		HandlingMinutes  int              `json:"handlingMinutes"`
		Functions        []string         `json:"functions"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		req.CoverageKm = 5.0
	}

	fns := funcSet(req.Functions)

	var locID string
	err := h.DB.QueryRow(`INSERT INTO locations (name, latitude, longitude, coverage_km, handling_minutes, collection_point, transfer_point, hub, laboratory)
		VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) RETURNING id`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes,
		fns["collection_point"], fns["transfer_point"], fns["hub"], fns["laboratory"]).Scan(&locID)
	if err != nil {
		middleware.WriteError(w, 500, "Internal error", "internal_error")
		return
	}

	// Default capacity
