func (h *Handler) configureCapacity(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		ResourceId          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits int    `json:"cooledCapacityUnits"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	// Check if it's a location
	var count int
	h.DB.QueryRow("SELECT COUNT(*) FROM locations WHERE id = $1", req.ResourceId).Scan(&count)
	if count > 0 {
		h.DB.Exec(`INSERT INTO location_capacity (location_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1, $2, 0, $3, 0) ON CONFLICT (location_id) DO UPDATE SET capacity_units = $2, cooled_capacity_units = $3`,
			req.ResourceId, req.CapacityUnits, req.CooledCapacityUnits)
	} else {
		// Try connection
		h.DB.Exec(`INSERT INTO connection_capacity (connection_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1, $2, 0, $3, 0) ON CONFLICT (connection_id) DO UPDATE SET capacity_units = $2, cooled_capacity_units = $3`,
			req.ResourceId, req.CapacityUnits, req.CooledCapacityUnits)
	}

	middleware.WriteData(w, 200, map[string]interface{}{
		"resourceId":         req.ResourceId,
		"capacityUnits":      req.CapacityUnits,
		"cooledCapacityUnits": req.CooledCapacityUnits,
	})
	_ = userID
	_ = activeRole
}

