func (h *Handler) collectAndSealSample(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		SampleId            string  `json:"sampleId"`
		AssignmentId        string  `json:"assignmentId"`
		CollectedAt         string  `json:"collectedAt"`
		ContainerType       string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey      string  `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	collectedAt, _ := time.Parse(time.RFC3339, req.CollectedAt)

	// Verify assignment
	var kind, status, wID string
	h.DB.QueryRow(`SELECT kind, status, worker_id FROM assignments WHERE id = $1`, req.AssignmentId).Scan(&kind, &status, &wID)
	if wID != userID || status != "accepted" {
		middleware.WriteError(w, 409, "Assignment not accepted", "collection_not_ready")
		return
	}

	// Get sample
	var sampleStatus string
	var tMin, tMax float64
	err := h.DB.QueryRow(`SELECT status, temperature_min_c, temperature_max_c FROM samples WHERE id = $1`, req.SampleId).Scan(&sampleStatus, &tMin, &tMax)
	if err != nil {
		middleware.WriteError(w, 404, "Sample not found", "not_found")
		return
	}

	_, err = h.DB.Exec(`UPDATE samples SET status = 'sealed', sealed = true, current_holder_id = $2, container_type = $3, updated_at = NOW() WHERE id = $1`, req.SampleId, userID, req.ContainerType)
	if err != nil {
		middleware.WriteError(w, 500, "Internal error", "internal_error")
		return
	}

	h.DB.Exec(`UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE id = $1`, req.AssignmentId)

	// Record checkpoint
	h.DB.Exec(`INSERT INTO handling_checkpoints (sample_id, recorded_by, container_type, observed_temperature_c) VALUES ($1, $2, $3, $4)`, req.SampleId, userID, req.ContainerType, req.ObservedTemperatureC)

	h.audit(userID, activeRole, activeRole, "collect_and_seal", "sample", req.SampleId, true, map[string]interface{}{"container": req.ContainerType})

	middleware.WriteData(w, 201, map[string]interface{}{
		"sampleId":         req.SampleId,
		"status":           "sealed",
		"collectedAt":      collectedAt,
		"containerType":    req.ContainerType,
		"temperatureObserved": req.ObservedTemperatureC,
	})
}

