	_, err := h.DB.Exec(`UPDATE sample_types SET qualified_collector_required = $2, required_qualification = $3, container_type = $4, temperature_min_c = $5, temperature_max_c = $6, requires_cooled_route = $7, batching_allowed = $8, updated_at = NOW() WHERE id = $1`,
