	var cpID string
	h.DB.QueryRow(`INSERT INTO handling_checkpoints (sample_id, recorded_by, container_type, observed_temperature_c) VALUES ($1, $2, $3, $4) RETURNING id`,
		req.SampleId, userID, req.ContainerType, req.ObservedTemperatureC).Scan(&cpID)

	// Check exception
	exception := false
	if req.ObservedTemperatureC < tMin || req.ObservedTemperatureC > tMax {
		exception = true
		h.DB.Exec(`INSERT INTO sample_exceptions (sample_id, exception_type, description, recorded_by) VALUES ($1, 'handling_noncompliant', 'Temperature out of range', $2)`, req.SampleId, userID)
	}

	h.audit(userID, activeRole, activeRole, "record_handling_checkpoint", "sample", req.SampleId, true, map[string]interface{}{
		"container": req.ContainerType,
		"temp":      req.ObservedTemperatureC,
		"exception": exception,
	})

	middleware.WriteData(w, 200, map[string]interface{}{
		"checkpointId":        cpID,
		"sampleId":            req.SampleId,
		"containerType":       req.ContainerType,
		"observedTemperatureC": req.ObservedTemperatureC,
		"exception":           exception,
	})
}

func (h *Handler) createUser(w http.ResponseWriter, r *http.Request) {
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		Username        string                   `json:"username"`
		Password        string                   `json:"password"`
		FullName        string                   `json:"fullName"`
		Roles           []string                 `json:"roles"`
		Qualifications  []string                 `json:"qualifications"`
		Certifications  []models.Certification   `json:"certifications"`
		AssignedLocationId string                `json:"assignedLocationId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	hashed, _ := h.AuthStore.HashPassword(req.Password)
	var userID string
	err := h.DB.QueryRow(`INSERT INTO users (username, password_hash, full_name) VALUES ($1, $2, $3) RETURNING id`,
		req.Username, hashed, req.FullName).Scan(&userID)
	if err != nil {
		middleware.WriteError(w, 409, "Username may exist", "concurrent_conflict")
		return
	}

	for _, role := range req.Roles {
		h.DB.Exec(`INSERT INTO user_roles (user_id, role) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, role)
	}

	for _, cert := range req.Certifications {
		var expires interface{} = nil
		if cert.ExpiresAt != nil {
			expires = *cert.ExpiresAt
		}
		h.DB.Exec(`INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1, $2, $3, $4) ON CONFLICT (user_id, code) DO UPDATE SET active = $3, expires_at = $4`, userID, cert.Code, cert.Active, expires)
	}

	if req.AssignedLocationId != "" {
		h.DB.Exec(`INSERT INTO user_assigned_locations (user_id, location_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, userID, req.AssignedLocationId)
	}

	middleware.WriteData(w, 201, map[string]interface{}{
		"userId":   userID,
		"username": req.Username,
		"roles":    req.Roles,
		"active":   true,
	})
}

func (h *Handler) updateUserAccess(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		UserId              string                   `json:"userId"`
		Roles               []string                 `json:"roles"`
		Qualifications      []string                 `json:"qualifications"`
		Certifications      []models.Certification   `json:"certifications"`
		Active              bool                     `json:"active"`
