	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		SampleTypeId     string           `json:"sampleTypeId"`
		OriginType       string           `json:"originType"`
		Origin           models.Coordinate `json:"origin"`
		OriginNodeId     string           `json:"originNodeId"`
		ContainerType    string           `json:"containerType"`
		ObservedTemperatureC float64      `json:"observedTemperatureC"`
		DeliveryDeadline string           `json:"deliveryDeadline"`
		IdempotencyKey   string           `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	if req.OriginType != "clinic" && req.OriginType != "node" {
		middleware.WriteError(w, 400, "Pre-sealed requires clinic or node origin", "invalid_origin_type")
		return
	}

	var containerType string
	var tMin, tMax float64
	h.DB.QueryRow(`SELECT container_type, temperature_min_c, temperature_max_c FROM sample_types WHERE id = $1`, req.SampleTypeId).Scan(&containerType, &tMin, &tMax)

	deadline, _ := time.Parse(time.RFC3339, req.DeliveryDeadline)

	var sampleID string
	err := h.DB.QueryRow(`INSERT INTO samples (request_id, sample_type_id, container_type, temperature_min_c, temperature_max_c, origin_lat, origin_lon, origin_type, delivery_deadline, status, sealed, current_holder_id, requester_id)
		VALUES (NULL, $1, $2, $3, $4, $5, $6, $7, $8, 'sealed', true, $9, $10) RETURNING id`,
		req.SampleTypeId, containerType, tMin, tMax,
		req.Origin.Latitude, req.Origin.Longitude, req.OriginType, deadline, userID, userID).Scan(&sampleID)
	if err != nil {
		middleware.WriteError(w, 500, "Internal error", "internal_error")
		return
	}

	// Record checkpoint
	h.DB.Exec(`INSERT INTO handling_checkpoints (sample_id, recorded_by, container_type, observed_temperature_c) VALUES ($1, $2, $3, $4)`, sampleID, userID, req.ContainerType, req.ObservedTemperatureC)

	h.audit(userID, activeRole, activeRole, "ingest_presealed", "sample", sampleID, true, nil)

	middleware.WriteData(w, 201, map[string]interface{}{
		"sampleId":     sampleID,
		"status":       "sealed",
		"containerType": req.ContainerType,
	})
}

func (h *Handler) cancelJourney(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyId           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var planVersion int
	var status string
	err := h.DB.QueryRow(`SELECT plan_version, status FROM journeys WHERE id = $1`, req.JourneyId).Scan(&planVersion, &status)
	if err != nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}
	if planVersion != req.ExpectedPlanVersion {
		middleware.WriteError(w, 409, "Stale plan version", "stale_plan")
		return
	}

	h.DB.Exec(`UPDATE journeys SET status = 'cancelled', updated_at = NOW() WHERE id = $1`, req.JourneyId)
	// Cancel assignments
	h.DB.Exec(`UPDATE assignments SET status = 'cancelled' WHERE journey_id = $1 AND status NOT IN ('completed','cancelled','declined')`, req.JourneyId)
	// Mark affected samples
	h.DB.Exec(`UPDATE samples SET status = 'cancelled' WHERE id IN (SELECT sample_id FROM assignments WHERE journey_id = $1 AND status = 'cancelled')`, req.JourneyId)

	h.audit(userID, activeRole, activeRole, "cancel_journey", "journey", req.JourneyId, true, map[string]interface{}{"reason": req.Reason})

	middleware.WriteData(w, 201, map[string]interface{}{
		"journeyId": req.JourneyId,
		"status":    "cancelled",
	})
}

