func (h *Handler) readSampleState(w http.ResponseWriter, r *http.Request) {
	_ = middleware.GetUserID(r.Context())
	sampleID := extractPathParam(r.URL.Path, "/api/read-sample-state/")

	var reqID, requesterID, status, containerType, originType, stID sql.NullString
	var oLat, oLon, tMin, tMax float64
	var reqAt, dl sql.NullTime
	var targetLab, activeJourney sql.NullString
	var llat, llon sql.NullFloat64
	var lrec sql.NullTime

	err := h.DB.QueryRow(`
		SELECT request_id, requester_id, status, container_type, temperature_min_c, temperature_max_c,
			origin_lat, origin_lon, origin_type, requested_at, delivery_deadline,
			target_laboratory_id, active_journey_id, latest_lat, latest_lon, location_recorded_at
		FROM samples WHERE id = $1`, sampleID).Scan(
		&reqID, &requesterID, &status, &containerType, &tMin, &tMax,
		&oLat, &oLon, &originType, &reqAt, &dl,
		&targetLab, &activeJourney, &llat, &llon, &lrec)
	if err != nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}

	// Get sample type ID and incompatibilities
	var stName, stContainer string
	var stQualReq, stCooled, stBatching bool
	var incompatibleTypes []string
	h.DB.QueryRow(`SELECT name, container_type, qualified_collector_required, requires_cooled_route, batching_allowed FROM sample_types WHERE id = (SELECT sample_type_id FROM samples WHERE id = $1)`, sampleID).Scan(&stName, &stContainer, &stQualReq, &stCooled, &stBatching)

	incRows, _ := h.DB.Query("SELECT incompatible_type_id FROM sample_type_incompatibilities WHERE sample_type_id = (SELECT sample_type_id FROM samples WHERE id = $1)", sampleID)
	if incRows != nil {
		defer incRows.Close()
		for incRows.Next() {
			var iid string
			incRows.Scan(&iid)
			incompatibleTypes = append(incompatibleTypes, iid)
		}
	}

	// Active assignment IDs
	activeAssignments := []string{}
	aRows, _ := h.DB.Query("SELECT id FROM assignments WHERE sample_id = $1 AND status IN ('offered','accepted')", sampleID)
	if aRows != nil {
		defer aRows.Close()
		for aRows.Next() {
			var aid string
			aRows.Scan(&aid)
			activeAssignments = append(activeAssignments, aid)
		}
	}

	// Get audit timeline
	timeline := getTimeline(h.DB, "sample", sampleID)

	state := models.SampleState{
		SampleId:                sampleID,
		RequestId:               reqID.String,
		RequesterId:             requesterID.String,
		Origin:                  models.Coordinate{Latitude: oLat, Longitude: oLon},
		OriginType:              originType.String,
		RequestedAt:             reqAt.Time,
		DeliveryDeadline:        dl.Time,
		SampleTypeId:            stID.String,
		ContainerType:           containerType.String,
		TemperatureMinC:         tMin,
		TemperatureMaxC:         tMax,
		IncompatibleSampleTypes: incompatibleTypes,
		Serviceability:          "serviceable",
		ActiveAssignmentIds:     activeAssignments,
		State:                   map[string]interface{}{"status": status.String},
		Timeline:                timeline,
		ActiveJourneyId:         activeJourney.String,
		TargetLaboratoryId:      targetLab.String,
		LocationStale:           isStale(lrec),
	}
	if llat.Valid {
		state.LatestLocation = &models.Coordinate{Latitude: llat.Float64, Longitude: llon.Float64}
	}
	if lrec.Valid {
		state.LocationRecordedAt = &lrec.Time
	}

	middleware.WriteData(w, 200, state)
	_ = userID
}

func (h *Handler) readSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())

	var req struct {
		SampleId string `json:"sampleId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var status string
	var sealed bool
	var currentHolder, activeJourney, receivedLab, pendingHO sql.NullString
	var llat, llon sql.NullFloat64
	var lrec sql.NullTime

	err := h.DB.QueryRow(`SELECT status, sealed, current_holder_id, active_journey_id, received_laboratory_id, latest_lat, latest_lon, location_recorded_at FROM samples WHERE id = $1`, req.SampleId).Scan(&status, &sealed, &currentHolder, &activeJourney, &receivedLab, &llat, &llon, &lrec)
	if err != nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}

	// Get pending handoff
	var pendingHandoff sql.NullString
	h.DB.QueryRow(`SELECT id FROM handoffs WHERE sample_id = $1 AND status = 'pending' LIMIT 1`, req.SampleId).Scan(&pendingHandoff)

	timeline := getTimeline(h.DB, "sample", req.SampleId)

	// Completed legs
	completedLegs := []string{}
	clRows, _ := h.DB.Query("SELECT id FROM journey_legs WHERE sample_id = $1 AND status = 'completed'", req.SampleId)
	if clRows != nil {
		defer clRows.Close()
		for clRows.Next() {
			var lid string
			clRows.Scan(&lid)
			completedLegs = append(completedLegs, lid)
		}
	}

	// Active replacement plans
	activePlans := []string{}
	apRows, _ := h.DB.Query("SELECT id FROM journeys WHERE parent_journey_id IN (SELECT active_journey_id FROM samples WHERE id = $1) AND replan_status IS NULL AND status NOT IN ('cancelled','completed')", req.SampleId)
	if apRows != nil {
		defer apRows.Close()
		for apRows.Next() {
			var pid string
			apRows.Scan(&pid)
			activePlans = append(activePlans, pid)
		}
	}

	// Exceptions
	excRows, _ := h.DB.Query("SELECT exception_type, description FROM sample_exceptions WHERE sample_id = $1 ORDER BY created_at DESC LIMIT 1", req.SampleId)
	var exception map[string]interface{}
	if excRows != nil {
		defer excRows.Close()
		if excRows.Next() {
			var etype, edesc string
			excRows.Scan(&etype, &edesc)
			exception = map[string]interface{}{"type": etype, "description": edesc}
		}
	}

	lifecycle := models.SampleLifecycle{
		SampleId:                 req.SampleId,
		Status:                   status,
		Sealed:                   sealed,
		CompletedLegIds:          completedLegs,
		ActiveReplacementPlanIds: activePlans,
		Timeline:                 timeline,
		ActiveJourneyId:          activeJourney.String,
		CurrentHolderId:          currentHolder.String,
		ReceivedLaboratoryId:     receivedLab.String,
		Exception:                exception,
		PendingHandoffId:         pendingHandoff.String,
		LocationStale:            isStale(lrec),
	}
	if llat.Valid {
		lifecycle.LatestLocation = &models.Coordinate{Latitude: llat.Float64, Longitude: llon.Float64}
	}
	if lrec.Valid {
		lifecycle.LocationRecordedAt = &lrec.Time
	}

	middleware.WriteData(w, 200, lifecycle)
	_ = userID
}

