func (h *Handler) reportDisruption(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceId     string `json:"resourceId"`
		DisruptionType string `json:"disruptionType"`
		Description    string `json:"description"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	h.audit(userID, activeRole, activeRole, "report_disruption", req.ResourceType, req.ResourceId, true, map[string]interface{}{
		"type":        req.DisruptionType,
		"description": req.Description,
	})

	// Return affected journeys
	affected := []string{}
	if req.ResourceType == "location" {
		// Find journeys with stops at this location
		rows, _ := h.DB.Query(`SELECT DISTINCT j.id FROM journeys j JOIN journey_stops js ON js.journey_id = j.id WHERE js.location_id = $1 AND j.status NOT IN ('completed','cancelled')`, req.ResourceId)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var jid string
				rows.Scan(&jid)
				affected = append(affected, jid)
			}
		}
	} else if req.ResourceType == "connection" {
		rows, _ := h.DB.Query(`SELECT DISTINCT j.id FROM journeys j JOIN journey_legs jl ON jl.journey_id = j.id WHERE (jl.from_location_id = (SELECT from_location_id FROM connections WHERE id = $1) AND jl.to_location_id = (SELECT to_location_id FROM connections WHERE id = $1)) AND j.status NOT IN ('completed','cancelled')`, req.ResourceId)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var jid string
				rows.Scan(&jid)
				affected = append(affected, jid)
			}
		}
	}

	middleware.WriteData(w, 200, map[string]interface{}{
		"acknowledged":      true,
		"affectedJourneyIds": affected,
	})
}

func (h *Handler) updateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		AssignmentId   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var workerID, kind, assnStatus string
	var sampleID sql.NullString
	h.DB.QueryRow(`SELECT worker_id, kind, status, sample_id FROM assignments WHERE id = $1`, req.AssignmentId).Scan(&workerID, &kind, &assnStatus, &sampleID)
	if workerID != userID {
		middleware.WriteError(w, 403, "Not your assignment", "ineligible_worker")
		return
	}

	validTransition := map[string]bool{
		"accepted": true, "at_pickup": true, "picked_up": true,
		"in_transit": true, "arrived": true, "delivered": true,
		"in_progress": true, "completed": true,
	}
	if !validTransition[req.Status] {
		middleware.WriteError(w, 400, "Invalid status transition", "invalid_json")
		return
	}

	occurredAt, _ := time.Parse(time.RFC3339, req.OccurredAt)

	h.DB.Exec(`UPDATE assignments SET status = $2, updated_at = NOW() WHERE id = $1`, req.AssignmentId, req.Status)
	if sampleID.Valid && req.Status == "delivered" {
		h.DB.Exec(`UPDATE samples SET status = 'delivered', updated_at = NOW() WHERE id = $1`, sampleID.String)
	}

	h.audit(userID, activeRole, activeRole, "update_progress", "assignment", req.AssignmentId, true, map[string]interface{}{"status": req.Status})

	middleware.WriteData(w, 201, map[string]interface{}{
		"assignmentId": req.AssignmentId,
		"sampleId":     sampleID.String,
		"status":       req.Status,
		"occurredAt":   occurredAt,
	})
}

