package handlers

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"github.com/lab-sample-pickup-delivery/backend/internal/auth"
	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
	"github.com/lab-sample-pickup-delivery/backend/internal/models"
)

type AuthHandler struct {
	DB        *sql.DB
	AuthStore *auth.AuthStore
}

func (h *AuthHandler) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req models.AuthRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}
	if req.Username == "" || req.Password == "" {
		middleware.WriteError(w, 400, "Username and password required", "invalid_json")
		return
	}

	var userID, hash, fullName string
	err := h.DB.QueryRow("SELECT id, password_hash, full_name FROM users WHERE username = $1 AND active = true", req.Username).Scan(&userID, &hash, &fullName)
	if err != nil || !h.AuthStore.CheckPassword(hash, req.Password) {
		middleware.WriteError(w, 401, "Invalid credentials", "invalid_credentials")
		return
	}

	roles, _ := h.AuthStore.GetUserRoles(userID)
	token, err := h.AuthStore.CreateSession(userID)
	if err != nil {
		middleware.WriteError(w, 500, "Internal error", "internal_error")
		return
	}

	middleware.WriteData(w, 200, models.AuthData{
		SessionToken: token,
		UserId:       userID,
		Roles:        roles,
		Username:     req.Username,
	})
}

func (h *AuthHandler) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	var req models.SelectRoleRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}
	if req.Role == "" {
		middleware.WriteError(w, 400, "Role required", "invalid_json")
		return
	}
	hasRole, _ := h.AuthStore.HasRole(userID, req.Role)
	if !hasRole {
		middleware.WriteError(w, 403, "Role not assigned", "forbidden")
		return
	}
	if err := h.AuthStore.SetActiveRole(userID, req.Role); err != nil {
		middleware.WriteError(w, 500, "Internal error", "internal_error")
		return
	}
	roles, _ := h.AuthStore.GetUserRoles(userID)
	middleware.WriteData(w, 200, map[string]interface{}{
		"userId":     userID,
		"activeRole": req.Role,
		"roles":      roles,
	})
}

func (h *AuthHandler) ReadUser(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	pathUserID := extractPathParam(r.URL.Path, "/api/read-user/")
	if pathUserID == "" {
		middleware.WriteError(w, 400, "User ID required", "invalid_json")
		return
	}
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator && userID != pathUserID {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var username, fullName string
	var active bool
	var createdAt time.Time
	err := h.DB.QueryRow("SELECT username, full_name, active, created_at FROM users WHERE id = $1", pathUserID).Scan(&username, &fullName, &active, &createdAt)
	if err != nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}
	roles, _ := h.AuthStore.GetUserRoles(pathUserID)

	certs := []models.Certification{}
	rows, _ := h.DB.Query("SELECT code, active, expires_at FROM user_certifications WHERE user_id = $1", pathUserID)
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var c models.Certification
			var exp sql.NullTime
			rows.Scan(&c.Code, &c.Active, &exp)
			if exp.Valid {
				c.ExpiresAt = &exp.Time
			}
			certs = append(certs, c)
		}
	}

	var assignedLoc sql.NullString
	h.DB.QueryRow("SELECT location_id FROM user_assigned_locations WHERE user_id = $1 LIMIT 1", pathUserID).Scan(&assignedLoc)

	activeRoleForUser, _ := h.AuthStore.GetActiveRole(pathUserID)

	data := map[string]interface{}{
		"userId":     pathUserID,
		"username":   username,
		"fullName":   fullName,
		"roles":      roles,
		"activeRole": activeRoleForUser,
		"active":     active,
		"certifications": certs,
	}
	if assignedLoc.Valid {
		data["assignedLocationId"] = assignedLoc.String
	}
	middleware.WriteData(w, 200, data)
}

func (h *AuthHandler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	username := middleware.GetUsername(r.Context())
	roles, _ := h.AuthStore.GetUserRoles(userID)
	activeRole, _ := h.AuthStore.GetActiveRole(userID)
	lookups := buildLookups(h.DB)

	middleware.WriteData(w, 200, map[string]interface{}{
		"user": map[string]interface{}{
			"userId":     userID,
			"username":   username,
			"roles":      roles,
			"activeRole": activeRole,
		},
		"lookups": lookups,
	})
}

func buildLookups(db *sql.DB) map[string]interface{} {
	lookups := map[string]interface{}{}

	// Sample types
	sampleTypes := []map[string]interface{}{}
	rows, _ := db.Query("SELECT id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed FROM sample_types")
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var id, name, qual, container string
			var reqQual, cooled, batching bool
			var minT, maxT float64
			rows.Scan(&id, &name, &reqQual, &qual, &container, &minT, &maxT, &cooled, &batching)
			st := map[string]interface{}{
				"sampleTypeId":                id,
				"name":                        name,
				"qualifiedCollectorRequired": reqQual,
				"requiredQualification":       qual,
				"containerType":              container,
				"temperatureMinC":            minT,
				"temperatureMaxC":            maxT,
				"requiresCooledRoute":        cooled,
				"batchingAllowed":            batching,
			}
			incRows, _ := db.Query("SELECT incompatible_type_id FROM sample_type_incompatibilities WHERE sample_type_id = $1", id)
			if incRows != nil {
				incompat := []string{}
				for incRows.Next() {
					var incID string
					incRows.Scan(&incID)
					incompat = append(incompat, incID)
				}
				st["incompatibleSampleTypes"] = incompat
				incRows.Close()
			}
			sampleTypes = append(sampleTypes, st)
		}
	}
	lookups["sampleTypes"] = sampleTypes

	// Locations
	locations := []map[string]interface{}{}
	locRows, _ := db.Query("SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, collection_point, transfer_point, hub, laboratory FROM locations")
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var id, name string
			var lat, lon, cov float64
			var handling int
			var active, cp, tp, hub, lab bool
			locRows.Scan(&id, &name, &lat, &lon, &cov, &handling, &active, &cp, &tp, &hub, &lab)
			loc := map[string]interface{}{
				"locationId": id, "name": name,
				"coordinate":       map[string]interface{}{"latitude": lat, "longitude": lon},
				"coverageKm":       cov,
				"handlingMinutes":  handling,
				"active":           active,
				"functions": map[string]interface{}{
					"collection_point": cp, "transfer_point": tp, "hub": hub, "laboratory": lab,
				},
			}
			locations = append(locations, loc)
		}
	}
	lookups["locations"] = locations

	// Connections
	connections := []map[string]interface{}{}
	connRows, _ := db.Query("SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections")
	if connRows != nil {
		defer connRows.Close()
		for connRows.Next() {
			var id, fl, tl string
			var tm int
			var cost float64
			var cooled, active bool
			connRows.Scan(&id, &fl, &tl, &tm, &cost, &cooled, &active)
			connections = append(connections, map[string]interface{}{
				"connectionId": id, "fromLocationId": fl, "toLocationId": tl,
				"travelMinutes": tm, "costUnits": cost, "cooled": cooled, "active": active,
			})
		}
	}
	lookups["connections"] = connections

	// Users
	users := []map[string]interface{}{}
	uRows, _ := db.Query("SELECT id, username, full_name, active FROM users")
	if uRows != nil {
		defer uRows.Close()
		for uRows.Next() {
			var id, uname, fn string
			var active bool
			uRows.Scan(&id, &uname, &fn, &active)
			usr := map[string]interface{}{"userId": id, "username": uname, "fullName": fn, "active": active}
			rRows, _ := db.Query("SELECT role FROM user_roles WHERE user_id = $1", id)
			if rRows != nil {
				rl := []string{}
				for rRows.Next() {
					var role string
					rRows.Scan(&role)
					rl = append(rl, role)
				}
				usr["roles"] = rl
				rRows.Close()
			}
			users = append(users, usr)
		}
	}
	lookups["users"] = users

	return lookups
}

