func (h *Handler) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleRequester && activeRole != models.RoleAdministrator && activeRole != models.RoleDispatcher {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		Origin               models.Coordinate `json:"origin"`
		OriginType           string            `json:"originType"`
		OriginNodeId         string            `json:"originNodeId"`
		SampleTypeId         string            `json:"sampleTypeId"`
		RequestedAt          string            `json:"requestedAt"`
		DeliveryDeadline     string            `json:"deliveryDeadline"`
		EarliestCollectionAt string            `json:"earliestCollectionAt"`
		LatestCollectionAt   string            `json:"latestCollectionAt"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	err := h.DB.QueryRow(`SELECT name FROM sample_types WHERE id = $1`, req.SampleTypeId).Err()
	if err != nil {
		middleware.WriteError(w, 404, "Sample type not found", "not_found")
		return
	}

	reqTime, _ := time.Parse(time.RFC3339, req.RequestedAt)
	deadline, _ := time.Parse(time.RFC3339, req.DeliveryDeadline)
	if !deadline.After(reqTime) {
		middleware.WriteData(w, 200, map[string]interface{}{"serviceable": false, "reason": "deadline_not_future"})
		return
	}
	if req.OriginType == "" {
		req.OriginType = "home"
	}

	var nearestLocID string
	var nearestLat, nearestLon, nearestCov float64
	err = h.DB.QueryRow(`SELECT id, latitude, longitude, coverage_km FROM locations WHERE active = true AND collection_point = true ORDER BY point(latitude, longitude) <-> point($1, $2) LIMIT 1`,
		req.Origin.Latitude, req.Origin.Longitude).Scan(&nearestLocID, &nearestLat, &nearestLon, &nearestCov)
	if err != nil {
		middleware.WriteData(w, 200, map[string]interface{}{"serviceable": false, "reason": "outside_service_region"})
		return
	}

	dist := haversine(req.Origin.Latitude, req.Origin.Longitude, nearestLat, nearestLon)
	if dist > nearestCov {
		middleware.WriteData(w, 200, map[string]interface{}{"serviceable": false, "reason": "outside_service_region"})
		return
	}

	var labCount int
	h.DB.QueryRow(`SELECT COUNT(*) FROM laboratory_acceptance la JOIN locations l ON l.id = la.location_id WHERE la.sample_type_id = $1 AND la.accepts = true AND l.active = true AND l.laboratory = true`, req.SampleTypeId).Scan(&labCount)
	if labCount == 0 {
		middleware.WriteData(w, 200, map[string]interface{}{"serviceable": false, "reason": "laboratory_rejects_type"})
		return
	}

	region := []models.ServiceabilityRegion{}
	locRows, _ := h.DB.Query(`SELECT id, name, latitude, longitude, coverage_km FROM locations WHERE active = true AND collection_point = true`)
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var sr models.ServiceabilityRegion
			locRows.Scan(&sr.LocationId, &sr.Name, &sr.Latitude, &sr.Longitude, &sr.CoverageKm)
			region = append(region, sr)
		}
	}

	h.audit(userID, activeRole, "check_serviceability", "sample_type", req.SampleTypeId, true, map[string]interface{}{"serviceable": true, "lat": req.Origin.Latitude, "lon": req.Origin.Longitude})

	middleware.WriteData(w, 200, map[string]interface{}{
		"serviceable":                 true,
		"reason":                      "serviceable",
		"recommendedCollectionNodeId": nearestLocID,
		"estimatedDistanceKm":         dist,
		"region":                      region,
	})
}

