action.file_text:
package handlers

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"time"

	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
	"github.com/lab-sample-pickup-delivery/backend/internal/models"
)

func (h *Handler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	pending := []interface{}{}
	inProgress := []interface{}{}
	completed := []interface{}{}

	switch activeRole {
	case models.RoleRequester:
		sRows, _ := h.DB.Query(`SELECT id, request_id, status, origin_lat, origin_lon, delivery_deadline, latest_lat, latest_lon, location_recorded_at FROM samples WHERE requester_id = $1 ORDER BY created_at DESC`, userID)
		if sRows != nil {
			defer sRows.Close()
			for sRows.Next() {
				var id, reqID, status string
				var oLat, oLon float64
				var dl sql.NullTime
				var llat, llon sql.NullFloat64
				var lrec sql.NullTime
				sRows.Scan(&id, &reqID, &status, &oLat, &oLon, &dl, &llat, &llon, &lrec)
				swi := models.SampleWorkItem{Kind: "sample", SampleId: id, RequestId: reqID, Status: status, History: []models.TimelineEntry{}, LocationStale: isStale(lrec)}
				if dl.Valid {
					swi.DeliveryDeadline = &dl.Time
				}
				switch status {
				case "requested", "planned":
					pending = append(pending, swi)
				case "sealed", "in_transit":
					inProgress = append(inProgress, swi)
				case "delivered", "received", "cancelled":
					completed = append(completed, swi)
				default:
					pending = append(pending, swi)
				}
			}
		}

	default:
		// Generic: get assignments and samples held
		aRows, _ := h.DB.Query(`SELECT id, kind, sample_id, status, journey_id, from_location_id, to_location_id, offer_expires_at FROM assignments WHERE worker_id = $1 ORDER BY created_at DESC LIMIT 100`, userID)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var id, kind, sampleID, status, journeyID, fl, tl sql.NullString
				var expires sql.NullTime
				aRows.Scan(&id, &kind, &sampleID, &status, &journeyID, &fl, &tl, &expires)
				item := models.AssignmentWorkItem{Kind: kind.String, AssignmentId: id.String, SampleId: sampleID.String, Status: status.String, JourneyId: journeyID.String, FromLocationId: fl.String, ToLocationId: tl.String, History: []models.TimelineEntry{}}
				if expires.Valid {
					item.OfferExpiresAt = &expires.Time
				}
				switch status.String {
				case "offered":
					pending = append(pending, item)
				case "accepted":
					inProgress = append(inProgress, item)
				case "completed", "declined", "cancelled":
					completed = append(completed, item)
				}
			}
		}
		// Samples held by this user
		sRows, _ := h.DB.Query(`SELECT id, request_id, status, origin_lat, origin_lon, delivery_deadline, latest_lat, latest_lon, location_recorded_at FROM samples WHERE current_holder_id = $1`, userID)
		if sRows != nil {
			defer sRows.Close()
			for sRows.Next() {
				var id, reqID, status string
				var oLat, oLon float64
				var dl sql.NullTime
				var llat, llon sql.NullFloat64
				var lrec sql.NullTime
				sRows.Scan(&id, &reqID, &status, &oLat, &oLon, &dl, &llat, &llon, &lrec)
				swi := models.SampleWorkItem{Kind: "sample", SampleId: id, RequestId: reqID, Status: status, History: []models.TimelineEntry{}, LocationStale: isStale(lrec)}
				inProgress = append(inProgress, swi)
			}
		}
	}

	middleware.WriteData(w, 200, models.RoleWork{Pending: pending, InProgress: inProgress, Completed: completed})
}

func (h *Handler) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		AssignmentId    string `json:"assignmentId"`
		IdempotencyKey  string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var kind, status, workerID string
	err := h.DB.QueryRow(`SELECT kind, status, worker_id FROM assignments WHERE id = $1`, req.AssignmentId).Scan(&kind, &status, &workerID)
	if err != nil {
		middleware.WriteError(w, 404, "Assignment not found", "not_found")
		return
	}
	if workerID != userID {
		middleware.WriteError(w, 403, "Not offered to you", "offer_not_offered")
		return
	}
	if status != "offered" {
		middleware.WriteError(w, 409, "Assignment not available", "offer_not_available")
		return
	}
	h.DB.Exec(`UPDATE assignments SET status = 'accepted', updated_at = NOW() WHERE id = $1`, req.AssignmentId)
	h.audit(userID, activeRole, "accept_assignment", "assignment", req.AssignmentId, true, map[string]interface{}{"kind": kind})

	middleware.WriteData(w, 201, map[string]interface{}{
		"assignmentId": req.AssignmentId, "workerId": userID, "status": "accepted",
	})
}

func (h *Handler) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	_ = middleware.GetActiveRole(r.Context())

	var req struct {
		AssignmentId    string `json:"assignmentId"`
		Reason          string `json:"reason"`
		IdempotencyKey  string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var workerID, status string
	err := h.DB.QueryRow(`SELECT worker_id, status FROM assignments WHERE id = $1`, req.AssignmentId).Scan(&workerID, &status)
	if err != nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}
	if workerID != userID {
		middleware.WriteError(w, 403, "Not offered to you", "offer_not_offered")
		return
	}
	if status != "offered" {
		middleware.WriteError(w, 409, "Not available", "offer_not_available")
		return
	}
	h.DB.Exec(`UPDATE assignments SET status = 'declined', updated_at = NOW() WHERE id = $1`, req.AssignmentId)
	middleware.WriteData(w, 200, map[string]interface{}{"assignmentId": req.AssignmentId, "status": "declined"})
}

func (h *Handler) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		SampleId             string  `json:"sampleId"`
		AssignmentId         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	collectedAt, _ := time.Parse(time.RFC3339, req.CollectedAt)

	var kind, status, wID string
	h.DB.QueryRow(`SELECT kind, status, worker_id FROM assignments WHERE id = $1`, req.AssignmentId).Scan(&kind, &status, &wID)
	if wID != userID || status != "accepted" {
		middleware.WriteError(w, 409, "Assignment not accepted", "collection_not_ready")
		return
	}

	var sampleStatus string
	h.DB.QueryRow(`SELECT status FROM samples WHERE id = $1`, req.SampleId).Scan(&sampleStatus)

	h.DB.Exec(`UPDATE samples SET status = 'sealed', sealed = true, current_holder_id = $2, container_type = $3, updated_at = NOW() WHERE id = $1`, req.SampleId, userID, req.ContainerType)
	h.DB.Exec(`UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE id = $1`, req.AssignmentId)
	h.DB.Exec(`INSERT INTO handling_checkpoints (sample_id, recorded_by, container_type, observed_temperature_c) VALUES ($1, $2, $3, $4)`, req.SampleId, userID, req.ContainerType, req.ObservedTemperatureC)

