		"receivedAt":   receivedAt,
	})
}

func (h *Handler) RecordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		SampleId      string `json:"sampleId"`
		ExceptionType string `json:"exceptionType"`
		Description   string `json:"description"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var excID string
	h.DB.QueryRow(`INSERT INTO sample_exceptions (sample_id, exception_type, description, recorded_by) VALUES ($1, $2, $3, $4) RETURNING id`,
		req.SampleId, req.ExceptionType, req.Description, userID).Scan(&excID)

	h.audit(userID, activeRole, "record_exception", "sample", req.SampleId, true, map[string]interface{}{"type": req.ExceptionType})

	middleware.WriteData(w, 201, map[string]interface{}{
		"exceptionId":   excID,
		"sampleId":      req.SampleId,
		"exceptionType": req.ExceptionType,
		"description":   req.Description,
	})
}

