package handlers

import (
	"database/sql"
	"encoding/json"
	"net/http"

	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
	"github.com/lab-sample-pickup-delivery/backend/internal/models"
)

func (h *Handler) ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleDispatcher && activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}
	state := readFullOpsState(h.DB)
	middleware.WriteData(w, 200, state)
}

func (h *Handler) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		JourneyId string `json:"journeyId"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	plan := buildJourneyPlan(h.DB, req.JourneyId, activeRole, userID)
	if plan == nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}
	middleware.WriteData(w, 200, plan)
}

func (h *Handler) CancelJourney(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyId           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var planVersion int
	err := h.DB.QueryRow(`SELECT plan_version, status FROM journeys WHERE id = $1`, req.JourneyId).Scan(&planVersion, new(string))
	if err != nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}
	if planVersion != req.ExpectedPlanVersion {
		middleware.WriteError(w, 409, "Stale plan version", "stale_plan")
		return
	}

	h.DB.Exec(`UPDATE journeys SET status = 'cancelled', updated_at = NOW() WHERE id = $1`, req.JourneyId)
	h.DB.Exec(`UPDATE assignments SET status = 'cancelled' WHERE journey_id = $1 AND status NOT IN ('completed','cancelled','declined')`, req.JourneyId)
	h.DB.Exec(`UPDATE samples SET status = 'cancelled' WHERE id IN (SELECT sample_id FROM assignments WHERE journey_id = $1 AND status = 'cancelled')`, req.JourneyId)

	h.audit(userID, activeRole, "cancel_journey", "journey", req.JourneyId, true, map[string]interface{}{"reason": req.Reason})

	middleware.WriteData(w, 201, map[string]interface{}{"journeyId": req.JourneyId, "status": "cancelled"})
}

func (h *Handler) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyId           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	h.DB.Exec(`UPDATE journeys SET plan_version = plan_version + 1, updated_at = NOW() WHERE id = $1`, req.JourneyId)
	h.audit(userID, activeRole, "reroute_journey", "journey", req.JourneyId, true, nil)

	plan := buildFullJourneyPlan(h.DB, req.JourneyId)
	if plan == nil {
		middleware.WriteError(w, 404, "Not found", "not_found")
		return
	}
	middleware.WriteData(w, 201, plan)
}

func (h *Handler) SplitJourney(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyId           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIds           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var newID string
	h.DB.QueryRow(`INSERT INTO journeys (parent_journey_id, sample_ids, plan_version, route_mode, status, valid) VALUES ($1, $2, 1, 'direct', 'planned', true) RETURNING id`,
		req.JourneyId, toJSON(req.SampleIds)).Scan(&newID)

	var origJSON string
	h.DB.QueryRow(`SELECT sample_ids FROM journeys WHERE id = $1`, req.JourneyId).Scan(&origJSON)
	var origSamples []string
	json.Unmarshal([]byte(origJSON), &origSamples)

	splitMap := map[string]bool{}
	for _, sid := range req.SampleIds {
		splitMap[sid] = true
	}
	remaining := []string{}
	for _, sid := range origSamples {
		if !splitMap[sid] {
			remaining = append(remaining, sid)
		}
	}
	h.DB.Exec(`UPDATE journeys SET sample_ids = $2, updated_at = NOW() WHERE id = $1`, req.JourneyId, toJSON(remaining))

	h.audit(userID, activeRole, "split_journey", "journey", req.JourneyId, true, nil)

	origPlan := buildFullJourneyPlan(h.DB, req.JourneyId)
	splitPlan := buildFullJourneyPlan(h.DB, newID)

	middleware.WriteData(w, 201, map[string]interface{}{
		"journey":      origPlan,
		"splitJourney": splitPlan,
	})
}

func (h *Handler) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyIds     []string `json:"journeyIds"`
		IdempotencyKey string   `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}
	if len(req.JourneyIds) < 2 {
		middleware.WriteError(w, 400, "Need at least 2 journeys", "invalid_json")
		return
	}

	allSamples := []string{}
	for _, jid := range req.JourneyIds {
		var j string
		var s []string
		h.DB.QueryRow(`SELECT sample_ids FROM journeys WHERE id = $1`, jid).Scan(&j)
		json.Unmarshal([]byte(j), &s)
		allSamples = append(allSamples, s...)
	}

	var mergedID string
	h.DB.QueryRow(`INSERT INTO journeys (parent_journey_id, sample_ids, plan_version, route_mode, status, valid) VALUES (NULL, $1, 1, 'batched', 'planned', true) RETURNING id`,
		toJSON(allSamples)).Scan(&mergedID)

	for _, jid := range req.JourneyIds {
		h.DB.Exec(`UPDATE journeys SET status = 'cancelled', replan_status = 'replaced', replacement_journey_id = $2, updated_at = NOW() WHERE id = $1`, jid, mergedID)
	}

	h.audit(userID, activeRole, "merge_journeys", "journey", mergedID, true, nil)

	plan := buildFullJourneyPlan(h.DB, mergedID)
	middleware.WriteData(w, 201, plan)
}

func (h *Handler) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		JourneyId           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	h.DB.Exec(`UPDATE journeys SET plan_version = plan_version + 1, updated_at = NOW() WHERE id = $1`, req.JourneyId)
	h.audit(userID, activeRole, "edit_active_plan", "journey", req.JourneyId, true, nil)

	plan := buildFullJourneyPlan(h.DB, req.JourneyId)
	middleware.WriteData(w, 201, plan)
}

func (h *Handler) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if !middleware.IsAdminOrDispatcher(activeRole) {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceId     string `json:"resourceId"`
		DisruptionType string `json:"disruptionType"`
		Description    string `json:"description"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	h.audit(userID, activeRole, "report_disruption", req.ResourceType, req.ResourceId, true, map[string]interface{}{
		"type": req.DisruptionType, "description": req.Description,
	})

	affected := []string{}
	if req.ResourceType == "location" {
		rows, _ := h.DB.Query(`SELECT DISTINCT j.id FROM journeys j JOIN journey_stops js ON js.journey_id = j.id WHERE js.location_id = $1 AND j.status NOT IN ('completed','cancelled')`, req.ResourceId)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var jid string
				rows.Scan(&jid)
				affected = append(affected, jid)
			}
		}
	} else if req.ResourceType == "connection" {
		rows, _ := h.DB.Query(`SELECT DISTINCT j.id FROM journeys j JOIN journey_legs jl ON jl.journey_id = j.id WHERE (jl.from_location_id = (SELECT from_location_id FROM connections WHERE id = $1) AND jl.to_location_id = (SELECT to_location_id FROM connections WHERE id = $1)) AND j.status NOT IN ('completed','cancelled')`, req.ResourceId)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var jid string
				rows.Scan(&jid)
				affected = append(affected, jid)
			}
		}
	}

	middleware.WriteData(w, 200, map[string]interface{}{
		"acknowledged":       true,
		"affectedJourneyIds": affected,
	})
}

func (h *Handler) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleDispatcher && activeRole != models.RoleAdministrator {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		EntityType string `json:"entityType"`
		EntityId   string `json:"entityId"`
		ActorId    string `json:"actorId"`
		Action     string `json:"action"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}
	if req.Limit <= 0 {
		req.Limit = 50
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}

	orderClause := "DESC"
	if req.Order == "oldest_first" {
		orderClause = "ASC"
	}

	query := "SELECT id, actor_id, role, action, entity_type, entity_id, success, details, occurred_at FROM audit_log WHERE 1=1"
	countQuery := "SELECT COUNT(*) FROM audit_log WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if req.EntityType != "" {
		query += " AND entity_type = $" + itoa(argIdx)
		countQuery += " AND entity_type = $" + itoa(argIdx)
		args = append(args, req.EntityType)
		argIdx++
	}
	if req.EntityId != "" {
		query += " AND entity_id = $" + itoa(argIdx)
		countQuery += " AND entity_id = $" + itoa(argIdx)
		args = append(args, req.EntityId)
		argIdx++
	}
	if req.ActorId != "" {
		query += " AND actor_id = $" + itoa(argIdx)
		countQuery += " AND actor_id = $" + itoa(argIdx)
		args = append(args, req.ActorId)
		argIdx++
	}
	if req.Action != "" {
		query += " AND action = $" + itoa(argIdx)
		countQuery += " AND action = $" + itoa(argIdx)
		args = append(args, req.Action)
		argIdx++
	}

	var total int
	h.DB.QueryRow(countQuery, args...).Scan(&total)

	query += " ORDER BY occurred_at " + orderClause + " LIMIT $" + itoa(argIdx) + " OFFSET $" + itoa(argIdx+1)
	lc := argIdx
	args = append(args, req.Limit, req.Offset)

	rows, err := h.DB.Query(query, args...)
	if err != nil {
		middleware.WriteError(w, 500, "Query error", "internal_error")
		return
	}
	defer rows.Close()

	entries := []models.AuditEntry{}
	for rows.Next() {
		var e models.AuditEntry
		var details string
		rows.Scan(&e.AuditId, &e.ActorId, &e.Role, &e.Action, &e.EntityType, &e.EntityId, &e.Success, &details, &e.OccurredAt)
		json.Unmarshal([]byte(details), &e.Details)
		entries = append(entries, e)
	}

	hasMore := req.Offset+len(entries) < total
	nextOffset := req.Offset + req.Limit
	if !hasMore {
		nextOffset = 0
	}

	middleware.WriteData(w, 200, models.AuditSearchResult{
		Entries:    entries,
		Total:      total,
		Returned:   len(entries),
		Offset:     req.Offset,
		Limit:      req.Limit,
		Order:      req.Order,
		HasMore:    hasMore,
		NextOffset: nextOffset,
	})
	_ = lc
}

func itoa(i int) string {
	return fmt.Sprintf("%d", i)
}

// buildJourneyPlan creates a plan based on role access
func buildJourneyPlan(db *sql.DB, journeyID, role, userID string) interface{} {
	var routeMode, status string
	var planVersion int
	var parentID sql.NullString
	var sampleIDsJSON string
	var estDelivery sql.NullTime

	err := db.QueryRow(`SELECT route_mode, status, plan_version, parent_journey_id, sample_ids, estimated_delivery_at FROM journeys WHERE id = $1`, journeyID).Scan(&routeMode, &status, &planVersion, &parentID, &sampleIDsJSON, &estDelivery)
	if err != nil {
		return nil
	}

	var sampleIDs []string
	json.Unmarshal([]byte(sampleIDsJSON), &sampleIDs)

	if role == models.RoleRequester {
		plan := models.RequesterJourneyPlan{
			JourneyId:   journeyID,
			SampleIds:   sampleIDs,
			RouteMode:   routeMode,
			Status:      status,
			PlanVersion: planVersion,
			Legs:        []interface{}{},
		}
		if parentID.Valid {
			plan.ParentJourneyId = parentID.String
		}
		if estDelivery.Valid {
			plan.EstimatedDeliveryAt = &estDelivery.Time
		}
		plan.OrderedStops = readStops(db, journeyID)
		legs := []interface{}{}
		lRows, _ := db.Query(`SELECT assignment_id, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM journey_legs WHERE journey_id = $1 ORDER BY sequence`, journeyID)
		if lRows != nil {
			defer lRows.Close()
			for lRows.Next() {
				var aid, status, fl, tl, wid, sid sql.NullString
				var seq int
				lRows.Scan(&aid, &seq, &status, &fl, &tl, &wid, &sid)
				leg := map[string]interface{}{"assignmentId": aid.String, "sequence": seq, "status": status.String}
				if fl.Valid {
					leg["fromLocationId"] = fl.String
				}
				if tl.Valid {
					leg["toLocationId"] = tl.String
				}
				legs = append(legs, leg)
			}
		}
		plan.Legs = legs
		return plan
	}

	if role == models.RoleCollectionProfessional || role == models.RoleDeliveryPartner || role == models.RoleNodeHandler || role == models.RoleLaboratoryTeam {
		assnIDs := []string{}
		aRows, _ := db.Query(`SELECT id FROM assignments WHERE journey_id = $1 AND worker_id = $2`, journeyID, userID)
		if aRows != nil {
			defer aRows.Close()
			for aRows.Next() {
				var aid string
				aRows.Scan(&aid)
				assnIDs = append(assnIDs, aid)
			}
		}

		wp := models.WorkerJourneyPlan{
			JourneyId:     journeyID,
			PlanVersion:   planVersion,
			RouteMode:     routeMode,
			Status:        status,
			Scope:         "assigned_legs",
			AssignmentIds: assnIDs,
			SampleIds:     sampleIDs,
			Legs:          []models.JourneyLeg{},
			OrderedStops:  readStops(db, journeyID),
		}
		if parentID.Valid {
			wp.ParentJourneyId = parentID.String
		}
		if estDelivery.Valid {
			wp.EstimatedDeliveryAt = &estDelivery.Time
		}
		lRows, _ := db.Query(`SELECT assignment_id, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM journey_legs WHERE journey_id = $1 AND worker_id = $2 ORDER BY sequence`, journeyID, userID)
		if lRows != nil {
			defer lRows.Close()
			for lRows.Next() {
				var leg models.JourneyLeg
				var aid, status, fl, tl, wid, sid sql.NullString
				var seq int
				lRows.Scan(&aid, &seq, &status, &fl, &tl, &wid, &sid)
				leg.AssignmentId = aid.String
				leg.Sequence = seq
				leg.Status = status.String
				if fl.Valid {
					leg.FromLocationId = fl.String
				}
				if tl.Valid {
					leg.ToLocationId = tl.String
				}
				if wid.Valid {
					leg.WorkerId = wid.String
				}
				if sid.Valid {
					leg.SampleId = sid.String
				}
				wp.Legs = append(wp.Legs, leg)
			}
		}
		return wp
	}

	return buildFullJourneyPlan(db, journeyID)
}

func buildFullJourneyPlan(db *sql.DB, journeyID string) *models.JourneyPlan {
	var routeMode, status string
	var planVersion int
	var parentID sql.NullString
	var sampleIDsJSON string
	var estDelivery sql.NullTime
	var totalCost sql.NullFloat64
	var capacityUsed, capacityAvail sql.NullInt64

	err := db.QueryRow(`SELECT route_mode, status, plan_version, parent_journey_id, sample_ids, estimated_delivery_at, total_cost_units, capacity_used, capacity_available FROM journeys WHERE id = $1`, journeyID).Scan(&routeMode, &status, &planVersion, &parentID, &sampleIDsJSON, &estDelivery, &totalCost, &capacityUsed, &capacityAvail)
	if err != nil {
		return nil
	}

	var sampleIDs []string
	json.Unmarshal([]byte(sampleIDsJSON), &sampleIDs)

	plan := &models.JourneyPlan{
		JourneyId:    journeyID,
		PlanVersion:  planVersion,
		RouteMode:    routeMode,
		Status:       status,
		SampleIds:    sampleIDs,
		OrderedStops: readStops(db, journeyID),
		Legs:         []models.JourneyLeg{},
		Valid:        true,
	}
	if parentID.Valid {
		plan.ParentJourneyId = parentID.String
	}
	if estDelivery.Valid {
		plan.EstimatedDeliveryAt = &estDelivery.Time
	}
	if totalCost.Valid {
		plan.TotalCostUnits = totalCost.Float64
	}
	if capacityUsed.Valid {
		plan.CapacityUsed = int(capacityUsed.Int64)
	}
	if capacityAvail.Valid {
		plan.CapacityAvailable = int(capacityAvail.Int64)
	}

	wIDs := []string{}
	wRows, _ := db.Query(`SELECT DISTINCT worker_id FROM journey_legs WHERE journey_id = $1 AND worker_id IS NOT NULL`, journeyID)
	if wRows != nil {
		defer wRows.Close()
		for wRows.Next() {
			var wid string
			wRows.Scan(&wid)
			wIDs = append(wIDs, wid)
		}
	}
	plan.AssignedWorkerIds = wIDs

	lRows, _ := db.Query(`SELECT assignment_id, sequence, status, from_location_id, to_location_id, worker_id, sample_id FROM journey_legs WHERE journey_id = $1 ORDER BY sequence`, journeyID)
	if lRows != nil {
		defer lRows.Close()
		for lRows.Next() {
			var leg models.JourneyLeg
			var aid, status, fl, tl, wid, sid sql.NullString
			var seq int
			lRows.Scan(&aid, &seq, &status, &fl, &tl, &wid, &sid)
			leg.AssignmentId = aid.String
			leg.Sequence = seq
			leg.Status = status.String
			if fl.Valid {
				leg.FromLocationId = fl.String
			}
			if tl.Valid {
				leg.ToLocationId = tl.String
			}
			if wid.Valid {
				leg.WorkerId = wid.String
			}
			if sid.Valid {
				leg.SampleId = sid.String
			}
			plan.Legs = append(plan.Legs, leg)
		}
	}

	return plan
}

func readStops(db *sql.DB, journeyID string) []models.JourneyStop {
	stops := []models.JourneyStop{}
	rows, _ := db.Query(`SELECT js.id, js.location_id, js.stop_type, js.sequence, js.estimated_at, js.dwell_minutes, js.completed_at, l.latitude, l.longitude FROM journey_stops js JOIN locations l ON l.id = js.location_id WHERE js.journey_id = $1 ORDER BY js.sequence`, journeyID)
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var s models.JourneyStop
			var lat, lon float64
			var completed sql.NullTime
			rows.Scan(&s.StopId, &s.LocationId, &s.StopType, &s.Sequence, &s.EstimatedAt, &s.DwellMinutes, &completed, &lat, &lon)
			s.Coordinate = &models.Coordinate{Latitude: lat, Longitude: lon}
			if completed.Valid {
				s.CompletedAt = &completed.Time
			}
			stops = append(stops, s)
		}
	}
	return stops
}

func readFullOpsState(db *sql.DB) *models.OperationsState {
	state := &models.OperationsState{
		Samples:     []map[string]interface{}{},
		Workers:     []map[string]interface{}{},
		Locations:   []models.OperationsLocation{},
		Connections: []models.OperationsConnection{},
		Routes:      []map[string]interface{}{},
		Handoffs:    []map[string]interface{}{},
		Delays:      []map[string]interface{}{},
		Exceptions:  []map[string]interface{}{},
	}

	sRows, _ := db.Query(`SELECT id, request_id, requester_id, status, origin_lat, origin_lon, delivery_deadline, current_holder_id, active_journey_id, latest_lat, latest_lon, location_recorded_at FROM samples ORDER BY created_at DESC`)
	if sRows != nil {
		defer sRows.Close()
		for sRows.Next() {
			var id, reqID, reqUserID, status sql.NullString
			var oLat, oLon float64
			var dl sql.NullTime
			var holder, journey sql.NullString
			var llat, llon sql.NullFloat64
			var lrec sql.NullTime
			sRows.Scan(&id, &reqID, &reqUserID, &status, &oLat, &oLon, &dl, &holder, &journey, &llat, &llon, &lrec)
			s := map[string]interface{}{"sampleId": id.String, "status": status.String, "locationStale": isStale(lrec)}
			if reqID.Valid {
				s["requestId"] = reqID.String
			}
			s["origin"] = models.Coordinate{Latitude: oLat, Longitude: oLon}
			if dl.Valid {
				s["deliveryDeadline"] = dl.Time
			}
			if holder.Valid {
				s["currentHolderId"] = holder.String
			}
			if journey.Valid {
				s["activeJourneyId"] = journey.String
			}
			if llat.Valid {
				s["latestLocation"] = models.Coordinate{Latitude: llat.Float64, Longitude: llon.Float64}
			}
			if lrec.Valid {
				s["locationRecordedAt"] = lrec.Time
			}
			state.Samples = append(state.Samples, s)
		}
	}

	wRows, _ := db.Query(`SELECT u.id, u.username, u.full_name, u.active FROM users u WHERE EXISTS (SELECT 1 FROM user_roles ur WHERE ur.user_id = u.id AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team'))`)
	if wRows != nil {
		defer wRows.Close()
		for wRows.Next() {
			var id, username, fullName string
			var active bool
			wRows.Scan(&id, &username, &fullName, &active)
			var assnCount int
			db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE worker_id = $1 AND status IN ('accepted','offered')`, id).Scan(&assnCount)
			roles, _ := getRoles(db, id)
			w := map[string]interface{}{
				"workerId": id, "fullName": fullName, "roles": roles,
				"available": active, "status": boolStatus(active),
				"capacityUnits": 10, "assignmentCount": assnCount, "locationStale": true,
			}
			state.Workers = append(state.Workers, w)
		}
	}

	lRows, _ := db.Query(`SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, collection_point, transfer_point, hub, laboratory FROM locations`)
	if lRows != nil {
		defer lRows.Close()
		for lRows.Next() {
			var ol models.OperationsLocation
			ol.Capacity = &models.Capacity{}
			lRows.Scan(&ol.Id, &ol.Name, &ol.Coordinate.Latitude, &ol.Coordinate.Longitude, &ol.CoverageKm, &ol.HandlingMinutes, &ol.Active, &ol.Functions.CollectionPoint, &ol.Functions.TransferPoint, &ol.Functions.Hub, &ol.Functions.Laboratory)
			ol.LocationId = ol.Id

			var cap, res, ccap, cres sql.NullInt64
			db.QueryRow(`SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM location_capacity WHERE location_id = $1`, ol.Id).Scan(&cap, &res, &ccap, &cres)
			if cap.Valid {
				ol.Capacity.CapacityUnits = int(cap.Int64)
				ol.Capacity.ReservedUnits = int(res.Int64)
				ol.Capacity.AvailableUnits = int(cap.Int64 - res.Int64)
				ol.Capacity.CooledCapacityUnits = int(ccap.Int64)
				ol.Capacity.CooledReservedUnits = int(cres.Int64)
				ol.Capacity.CooledAvailableUnits = int(ccap.Int64 - cres.Int64)
			}

			accTypes := []string{}
			aRows, _ := db.Query(`SELECT sample_type_id FROM laboratory_acceptance WHERE location_id = $1 AND accepts = true`, ol.Id)
			if aRows != nil {
				for aRows.Next() {
					var tid string
					aRows.Scan(&tid)
					accTypes = append(accTypes, tid)
				}
				aRows.Close()
			}
			ol.AcceptedSampleTypeIds = accTypes
			state.Locations = append(state.Locations, ol)
		}
	}

	cRows, _ := db.Query(`SELECT c.id, c.from_location_id, c.to_location_id, c.travel_minutes, c.cost_units, c.cooled, c.active FROM connections c`)
	if cRows != nil {
		defer cRows.Close()
		for cRows.Next() {
			var oc models.OperationsConnection
			oc.Capacity = &models.Capacity{}
			cRows.Scan(&oc.Id, &oc.FromLocationId, &oc.ToLocationId, &oc.TravelMinutes, &oc.CostUnits, &oc.Cooled, &oc.Active)
			oc.ConnectionId = oc.Id
			var cap, res, ccap, cres sql.NullInt64
			db.QueryRow(`SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connection_capacity WHERE connection_id = $1`, oc.Id).Scan(&cap, &res, &ccap, &cres)
			if cap.Valid {
				oc.Capacity.CapacityUnits = int(cap.Int64)
				oc.Capacity.ReservedUnits = int(res.Int64)
				oc.Capacity.AvailableUnits = int(cap.Int64 - res.Int64)
				oc.Capacity.CooledCapacityUnits = int(ccap.Int64)
				oc.Capacity.CooledReservedUnits = int(cres.Int64)
				oc.Capacity.CooledAvailableUnits = int(ccap.Int64 - cres.Int64)
			}
			state.Connections = append(state.Connections, oc)
		}
	}

	hoRows, _ := db.Query(`SELECT id, sample_id, from_user_id, to_user_id, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE status = 'pending'`)
	if hoRows != nil {
		defer hoRows.Close()
		for hoRows.Next() {
			var id, sid, from, to, status string
			var sc, rc bool
			hoRows.Scan(&id, &sid, &from, &to, &status, &sc, &rc)
			state.Handoffs = append(state.Handoffs, map[string]interface{}{
				"handoffId": id, "sampleId": sid, "fromUserId": from, "toUserId": to,
				"status": status, "senderConfirmed": sc, "receiverConfirmed": rc,
			})
		}
	}

	exRows, _ := db.Query(`SELECT id, sample_id, exception_type, description FROM sample_exceptions ORDER BY created_at DESC LIMIT 50`)
	if exRows != nil {
		defer exRows.Close()
		for exRows.Next() {
			var id, sid, etype, desc string
			exRows.Scan(&id, &sid, &etype, &desc)
			state.Exceptions = append(state.Exceptions, map[string]interface{}{
				"exceptionId": id, "sampleId": sid, "exceptionType": etype, "description": desc,
			})
		}
	}

	var minA, maxA sql.NullInt64
	db.QueryRow(`SELECT MIN(cnt), MAX(cnt) FROM (SELECT COUNT(*) as cnt FROM assignments WHERE status IN ('accepted','offered') GROUP BY worker_id) sub`).Scan(&minA, &maxA)
	if minA.Valid && maxA.Valid {
		state.AssignmentCountSpread = int(maxA.Int64 - minA.Int64)
	}

	var inel int
	db.QueryRow(`SELECT COUNT(*) FROM assignments WHERE status = 'offered' AND offer_expires_at < NOW()`).Scan(&inel)
	state.IneligibleAssignmentCount = inel

	return state
}

func boolStatus(active bool) string {
	if active {
		return "available"
	}
	return "unavailable"
}

import "fmt"

observation.old_content:
package handlers

import (
	"database/sql"
	"encoding/json"
	"net/http"

	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
