func (h *Handler) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	username := middleware.GetUsername(r.Context())
	roles, _ := h.AuthStore.GetUserRoles(userID)
	activeRole, _ := h.AuthStore.GetActiveRole(userID)

	// Get lookups
	sampleTypes := []map[string]interface{}{}
	rows, _ := h.DB.Query("SELECT id, name, qualified_collector_required, required_qualification, container_type, temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed FROM sample_types")
	if rows != nil {
		defer rows.Close()
		for rows.Next() {
			var id, name, qual, container string
			var reqQual, cooled, batching bool
			var minT, maxT float64
			rows.Scan(&id, &name, &reqQual, &qual, &container, &minT, &maxT, &cooled, &batching)
			st := map[string]interface{}{
				"sampleTypeId": id, "name": name,
				"qualifiedCollectorRequired": reqQual, "requiredQualification": qual,
				"containerType": container, "temperatureMinC": minT, "temperatureMaxC": maxT,
				"requiresCooledRoute": cooled, "batchingAllowed": batching,
			}
			incRows, _ := h.DB.Query("SELECT incompatible_type_id FROM sample_type_incompatibilities WHERE sample_type_id = $1", id)
			if incRows != nil {
				incompat := []string{}
				for incRows.Next() {
					var incID string
					incRows.Scan(&incID)
					incompat = append(incompat, incID)
				}
				st["incompatibleSampleTypes"] = incompat
				incRows.Close()
			}
			sampleTypes = append(sampleTypes, st)
		}
	}

	locations := []map[string]interface{}{}
	locRows, _ := h.DB.Query("SELECT id, name, latitude, longitude, coverage_km, handling_minutes, active, collection_point, transfer_point, hub, laboratory FROM locations")
	if locRows != nil {
		defer locRows.Close()
		for locRows.Next() {
			var id, name string
			var lat, lon, cov float64
			var handling int
			var active, cp, tp, hub, lab bool
			locRows.Scan(&id, &name, &lat, &lon, &cov, &handling, &active, &cp, &tp, &hub, &lab)
			loc := map[string]interface{}{
				"locationId": id, "name": name,
				"coordinate": map[string]interface{}{"latitude": lat, "longitude": lon},
				"coverageKm": cov, "handlingMinutes": handling, "active": active,
				"functions": map[string]interface{}{"collection_point": cp, "transfer_point": tp, "hub": hub, "laboratory": lab},
			}
			locations = append(locations, loc)
		}
	}

	connections := []map[string]interface{}{}
	connRows, _ := h.DB.Query("SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active FROM connections")
	if connRows != nil {
		defer connRows.Close()
		for connRows.Next() {
			var id, fl, tl string
			var tm int
			var cost float64
			var cooled, active bool
			connRows.Scan(&id, &fl, &tl, &tm, &cost, &cooled, &active)
			connections = append(connections, map[string]interface{}{
				"connectionId": id, "fromLocationId": fl, "toLocationId": tl,
				"travelMinutes": tm, "costUnits": cost, "cooled": cooled, "active": active,
			})
		}
	}

	users := []map[string]interface{}{}
	uRows, _ := h.DB.Query("SELECT id, username, full_name, active FROM users")
	if uRows != nil {
		defer uRows.Close()
		for uRows.Next() {
			var id, uname, fn string
			var active bool
			uRows.Scan(&id, &uname, &fn, &active)
			usr := map[string]interface{}{"userId": id, "username": uname, "fullName": fn, "active": active}
			rRows, _ := h.DB.Query("SELECT role FROM user_roles WHERE user_id = $1", id)
			if rRows != nil {
				rl := []string{}
				for rRows.Next() {
					var role string
					rRows.Scan(&role)
					rl = append(rl, role)
				}
				usr["roles"] = rl
				rRows.Close()
			}
			users = append(users, usr)
		}
	}

	middleware.WriteData(w, 200, map[string]interface{}{
		"user":    map[string]interface{}{"userId": userID, "username": username, "roles": roles, "activeRole": activeRole},
		"lookups": map[string]interface{}{"sampleTypes": sampleTypes, "locations": locations, "connections": connections, "users": users},
	})
}

