// SystemReadiness returns ready status
func (h *AuthHandler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	err := h.DB.Ping()
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(503)
		json.NewEncoder(w).Encode(models.ReadyResponse{Status: "starting"})
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	json.NewEncoder(w).Encode(models.ReadyResponse{Status: "ready"})
}

func (h *Handler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
