		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		Name            string            `json:"name"`
		Coordinate      models.Coordinate `json:"coordinate"`
		CoverageKm      float64           `json:"coverageKm"`
		HandlingMinutes int               `json:"handlingMinutes"`
		Functions       []string          `json:"functions"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}
	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		req.CoverageKm = 5.0
	}

	fns := funcSet(req.Functions)
	var locID string
	err := h.DB.QueryRow(`INSERT INTO locations (name, latitude, longitude, coverage_km, handling_minutes, collection_point, transfer_point, hub, laboratory) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9) RETURNING id`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes,
		fns["collection_point"], fns["transfer_point"], fns["hub"], fns["laboratory"]).Scan(&locID)
	if err != nil {
		middleware.WriteError(w, 500, "Internal error: "+err.Error(), "internal_error")
		return
	}

	h.DB.Exec(`INSERT INTO location_capacity (location_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1, 100, 0, 20, 0)`, locID)
	h.audit(userID, activeRole, "create_location", "location", locID, true, nil)

	loc := readLocation(h.DB, locID)
	middleware.WriteData(w, 201, loc)
