		return
	}

	h.DB.Exec(`UPDATE sample_types SET qualified_collector_required = $2, required_qualification = $3, container_type = $4, temperature_min_c = $5, temperature_max_c = $6, requires_cooled_route = $7, batching_allowed = $8, updated_at = NOW() WHERE id = $1`,
		req.SampleTypeId, req.QualifiedCollectorRequired, req.RequiredQualification, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, req.RequiresCooledRoute, req.BatchingAllowed)

	h.DB.Exec(`DELETE FROM sample_type_incompatibilities WHERE sample_type_id = $1`, req.SampleTypeId)
	for _, incID := range req.IncompatibleSampleTypes {
		h.DB.Exec(`INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_type_id) VALUES ($1, $2) ON CONFLICT DO NOTHING`, req.SampleTypeId, incID)
		h.DB.Exec(`INSERT INTO sample_type_incompatibilities (sample_type_id, incompatible_type_id) VALUES ($2, $1) ON CONFLICT DO NOTHING`, req.SampleTypeId, incID)
	}

	h.audit(userID, activeRole, "update_sample_type", "sample_type", req.SampleTypeId, true, nil)
	var name string
	h.DB.QueryRow(`SELECT name FROM sample_types WHERE id = $1`, req.SampleTypeId).Scan(&name)
	middleware.WriteData(w, 201, map[string]interface{}{"sampleTypeId": req.SampleTypeId, "name": name})
}

func (h *Handler) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())

	var req struct {
		ResourceId          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits int    `json:"cooledCapacityUnits"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var count int
	h.DB.QueryRow("SELECT COUNT(*) FROM locations WHERE id = $1", req.ResourceId).Scan(&count)
	if count > 0 {
		h.DB.Exec(`INSERT INTO location_capacity (location_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1, $2, 0, $3, 0) ON CONFLICT (location_id) DO UPDATE SET capacity_units = $2, cooled_capacity_units = $3`, req.ResourceId, req.CapacityUnits, req.CooledCapacityUnits)
	} else {
		h.DB.Exec(`INSERT INTO connection_capacity (connection_id, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units) VALUES ($1, $2, 0, $3, 0) ON CONFLICT (connection_id) DO UPDATE SET capacity_units = $2, cooled_capacity_units = $3`, req.ResourceId, req.CapacityUnits, req.CooledCapacityUnits)
	}

	_ = userID
	_ = activeRole
	middleware.WriteData(w, 200, map[string]interface{}{
		"resourceId": req.ResourceId, "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": req.CooledCapacityUnits,
	})
}

func (h *Handler) ConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	userID := middleware.GetUserID(r.Context())
	activeRole := middleware.GetActiveRole(r.Context())
	if activeRole != models.RoleAdministrator && activeRole != models.RoleLaboratoryTeam {
		middleware.WriteError(w, 403, "Forbidden", "forbidden")
		return
	}

	var req struct {
		LaboratoryId string `json:"laboratoryId"`
		SampleTypeId string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "Invalid JSON", "invalid_json")
		return
	}

	var accID string
	h.DB.QueryRow(`INSERT INTO laboratory_acceptance (location_id, sample_type_id, accepts) VALUES ($1, $2, $3) ON CONFLICT (location_id, sample_type_id) DO UPDATE SET accepts = $3 RETURNING id`,
		req.LaboratoryId, req.SampleTypeId, req.Accepts).Scan(&accID)

	h.audit(userID, activeRole, "configure_lab_acceptance", "laboratory", req.LaboratoryId, true, nil)
	middleware.WriteData(w, 200, map[string]interface{}{"acceptanceId": accID, "accepts": req.Accepts})
}

func (h *Handler) SystemReadiness(w http.ResponseWriter, r *http.Request) {
	var exists bool
	err := h.DB.QueryRow("SELECT EXISTS(SELECT 1 FROM users LIMIT 1)").Scan(&exists)
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(503)
		json.NewEncoder(w).Encode(models.ReadyResponse{Status: "starting"})
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	json.NewEncoder(w).Encode(models.ReadyResponse{Status: "ready"})
}

