action.file_text:
export interface User {
  id: string;
  username: string;
  roles: string[];
  active_role?: string;
  assigned_node_id?: string;
  assigned_laboratory_id?: string;
  certifications?: string[];
}

export interface Location {
  id: string;
  name: string;
  address: string;
  latitude: number;
  longitude: number;
  functions: string[];
  active: boolean;
  function_status: Record<string, boolean>;
  regular_capacity: number;
  cooled_capacity: number;
  regular_available: number;
  cooled_available: number;
}

export interface Connection {
  id: string;
  from_location_id: string;
  to_location_id: string;
  travel_time_minutes: number;
  distance_km: number;
  active: boolean;
  regular_capacity: number;
  cooled_capacity: number;
}

export interface SampleType {
  id: string;
  name: string;
  requires_cooling: boolean;
  requires_qualified_collector: boolean;
  incompatible_with: string[];
  container_type: string;
  temperature_min?: number;
  temperature_max?: number;
}

export interface Sample {
  id: string;
  request_id?: string;
  sample_type_id: string;
  sample_type_name?: string;
  status: string;
  current_holder_id?: string;
  current_holder_name?: string;
  current_location_id?: string;
  current_latitude?: number;
  current_longitude?: number;
  location_stale: boolean;
  last_update?: string;
  collected_at?: string;
  sealed_at?: string;
  origin_type: string;
  origin_address?: string;
  origin_latitude?: number;
  origin_longitude?: number;
  delivery_deadline?: string;
  collection_window_start?: string;
  collection_window_end?: string;
  receiving_laboratory_id?: string;
  active_journey_id?: string;
  requester_id?: string;
  requester_name?: string;
  container_type?: string;
  requires_cooling: boolean;
  handling_checkpoints?: HandlingCheckpoint[];
}

export interface HandlingCheckpoint {
  id: string;
  recorded_by: string;
  recorded_at: string;
  container_type: string;
  temperature?: number;
  out_of_range: boolean;
}

export interface JourneyPlan {
  journey_id: string;
  version: number;
  status: string;
  sample_id: string;
  stops: JourneyStop[];
  created_at: string;
  updated_at?: string;
}

export interface JourneyStop {
  id: string;
  sequence: number;
  location_id: string;
  location_name?: string;
  location_type: string;
  action: string;
  assigned_to?: string;
  assigned_name?: string;
  status: string;
  planned_arrival?: string;
  planned_departure?: string;
  actual_arrival?: string;
  actual_departure?: string;
  handoff_from?: string;
  handoff_to?: string;
}

export interface ServiceabilityRequest {
  origin_latitude: number;
  origin_longitude: number;
  origin_type: string;
  sample_type_id: string;
  delivery_deadline?: string;
}

export interface ServiceabilityResponse {
  serviceable: boolean;
  reason?: string;
  nearest_node_id?: string;
  nearest_node_name?: string;
  estimated_delivery_time?: string;
  eligible_laboratories?: string[];
  snapshot_version: number;
}

export interface CollectionRequest {
  origin_type: string;
  origin_address?: string;
  origin_latitude: number;
  origin_longitude: number;
  sample_type_id: string;
  collection_window_start: string;
  collection_window_end: string;
  delivery_deadline: string;
  notes?: string;
}

export interface HandoffRequest {
  sample_id: string;
  receiver_id: string;
}

export interface OperationsState {
  samples: Sample[];
  workers: WorkerState[];
  locations: Location[];
  exceptions: ExceptionInfo[];
}

export interface WorkerState {
  user_id: string;
  username: string;
  role: string;
  current_location?: { latitude: number; longitude: number; updated_at: string };
  active_assignment_id?: string;
  availability: string;
}

export interface ExceptionInfo {
  id: string;
  type: string;
  sample_id?: string;
  journey_id?: string;
  location_id?: string;
  description: string;
  created_at: string;
  resolved: boolean;
}

export interface Assignment {
  id: string;
  journey_id: string;
  stop_id: string;
  worker_id: string;
  role: string;
  status: string;
  offered_at?: string;
  accepted_at?: string;
  declined_at?: string;
  sample_id?: string;
  location_from?: string;
  location_to?: string;
  action: string;
}

export interface AuditEntry {
  id: string;
  timestamp: string;
  user_id: string;
  role: string;
  action: string;
  entity_type: string;
  entity_id: string;
  success: boolean;
  details?: Record<string, unknown>;
}

export interface TimelineEntry {
  timestamp: string;
  status: string;
  location?: string;
  actor?: string;
  details?: string;
}

export interface BootstrapData {
  sample_types: SampleType[];
  locations: Location[];
  roles: string[];
}

export interface AuthResponse {
  token: string;
  user: User;
}

export interface CreateUserRequest {
  username: string;
  password: string;
  roles: string[];
  assigned_node_id?: string;
  assigned_laboratory_id?: string;
  certifications?: string[];
}

export interface PaginatedResponse<T> {
  items: T[];
  total: number;
  page: number;
  page_size: number;
}

