import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './hooks/useAuth';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import NewRequest from './pages/NewRequest';
import SampleDetail from './pages/SampleDetail';
import WorkList from './pages/WorkList';
import OpsView from './pages/OpsView';
import AdminUsers from './pages/AdminUsers';
import AdminLocations from './pages/AdminLocations';
import AdminSampleTypes from './pages/AdminSampleTypes';
import AuditSearch from './pages/AuditSearch';
import Layout from './components/Layout';

export default function App() {
  const { user, loading } = useAuth();

  if (loading) return <div className="loading">Loading...</div>;
  if (!user) return <Login />;

  return (
    <Layout>
      <Routes>
        <Route path="/" element={<Dashboard />} />
        <Route path="/new-request" element={<NewRequest />} />
        <Route path="/samples/:id" element={<SampleDetail />} />
        <Route path="/work" element={<WorkList />} />
        <Route path="/ops" element={<OpsView />} />
        <Route path="/audit" element={<AuditSearch />} />
        <Route path="/admin/users" element={<AdminUsers />} />
        <Route path="/admin/locations" element={<AdminLocations />} />
        <Route path="/admin/sample-types" element={<AdminSampleTypes />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Layout>
  );
}

