import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';

export default function Layout({ children }: { children: React.ReactNode }) {
  const { user, logout, selectRole } = useAuth();
  const navigate = useNavigate();
  const isAdmin = user?.roles?.includes('administrator');
  const isDispatcher = user?.roles?.includes('dispatcher');
  const isReq = user?.roles?.includes('requester');
  const isCCP = user?.roles?.includes('certified_collection_professional');
  const isCourier = user?.roles?.includes('relay_courier');
  const isNodeHandler = user?.roles?.includes('node_handler');
  const isLabOp = user?.roles?.includes('laboratory_intake_operator');

  return (
    <div className="layout">
      <nav className="sidebar">
        <h2>Lab Sample</h2>
        <div className="role-selector">
          {user?.roles?.map((r) => (
            <button
              key={r}
              className={`role-chip${user.active_role === r ? ' active' : ''}`}
              onClick={() => selectRole(r)}
            >
              {r.replace(/_/g, ' ')}
            </button>
          ))}
        </div>

        <Link to="/">Dashboard</Link>

        {isReq && <Link to="/new-request">New Request</Link>}

        {(isCCP || isCourier || isNodeHandler || isLabOp) && (
          <Link to="/work">My Work</Link>
        )}

        {(isDispatcher || isAdmin) && (
          <>
            <h2 style={{ marginTop: '1rem' }}>Operations</h2>
            <Link to="/ops">Operations View</Link>
            <Link to="/audit">Audit Search</Link>
          </>
        )}

        {isAdmin && (
          <>
            <h2 style={{ marginTop: '1rem' }}>Admin</h2>
            <Link to="/admin/users">Users</Link>
            <Link to="/admin/locations">Locations</Link>
            <Link to="/admin/sample-types">Sample Types</Link>
          </>
        )}

        <div style={{ marginTop: 'auto', paddingTop: '1rem' }}>
          <div style={{ fontSize: '0.8rem', color: '#64748b' }}>
            {user?.username} ({user?.active_role?.replace(/_/g, ' ')})
          </div>
          <button className="btn" style={{ marginTop: '0.5rem', width: '100%' }} onClick={logout}>
            Logout
          </button>
        </div>
      </nav>
      <main className="main">{children}</main>
    </div>
  );
}

