import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { api } from '../services/api';
import type { BootstrapData, ServiceabilityResponse } from '../types/models';

export default function NewRequest() {
  const navigate = useNavigate();
  const [bootstrap, setBootstrap] = useState<BootstrapData | null>(null);
  const [originType, setOriginType] = useState('home');
  const [lat, setLat] = useState('');
  const [lon, setLon] = useState('');
  const [address, setAddress] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState('');
  const [collStart, setCollStart] = useState('');
  const [collEnd, setCollEnd] = useState('');
  const [deadline, setDeadline] = useState('');
  const [svcResult, setSvcResult] = useState<ServiceabilityResponse | null>(null);
  const [checking, setChecking] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  useEffect(() => {
    api.readBootstrap().then(setBootstrap).catch(() => {});
  }, []);

  const checkSvc = async () => {
    if (!lat || !lon || !sampleTypeId) {
      setError('Location and sample type required');
      return;
    }
    setChecking(true);
    setError('');
    try {
      const res = await api.checkServiceability({
        origin_latitude: parseFloat(lat),
        origin_longitude: parseFloat(lon),
        origin_type: originType,
        sample_type_id: sampleTypeId,
        delivery_deadline: deadline || undefined,
      });
      setSvcResult(res);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Check failed');
    } finally {
      setChecking(false);
    }
  };

  const submit = async () => {
    if (!svcResult?.serviceable) { setError('Location not serviceable'); return; }
    setSubmitting(true);
    setError('');
    try {
      await api.createCollectionRequest({
        origin_type: originType,
        origin_address: originType !== 'home' ? address : undefined,
        origin_latitude: parseFloat(lat),
        origin_longitude: parseFloat(lon),
        sample_type_id: sampleTypeId,
        collection_window_start: collStart,
        collection_window_end: collEnd,
        delivery_deadline: deadline,
      });
      setSuccess('Request created!');
      setTimeout(() => navigate('/'), 1500);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div>
      <h1 className="page-title">New Collection Request</h1>

      {error && <div className="error-msg">{error}</div>}
      {success && <div className="success-msg">{success}</div>}

      <div className="card" style={{ maxWidth: 600 }}>
        <div className="form-group">
          <label>Origin Type</label>
          <select value={originType} onChange={(e) => setOriginType(e.target.value)}>
            <option value="home">Home</option>
            <option value="clinic">Clinic</option>
            <option value="node">Collection Node</option>
          </select>
        </div>

        {originType !== 'home' && (
          <div className="form-group">
            <label>Address</label>
            <input value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Clinic or node address" />
          </div>
        )}

        <div className="grid grid-2">
          <div className="form-group">
            <label>Latitude</label>
            <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} placeholder="e.g. 51.5074" />
          </div>
          <div className="form-group">
            <label>Longitude</label>
            <input type="number" step="any" value={lon} onChange={(e) => setLon(e.target.value)} placeholder="e.g. -0.1278" />
          </div>
        </div>

        <div className="form-group">
          <label>Sample Type</label>
          <select value={sampleTypeId} onChange={(e) => setSampleTypeId(e.target.value)}>
            <option value="">-- Select --</option>
            {bootstrap?.sample_types?.map((st) => (
              <option key={st.id} value={st.id}>{st.name}</option>
            ))}
          </select>
        </div>

        <div className="grid grid-2">
          <div className="form-group">
            <label>Collection Start</label>
            <input type="datetime-local" value={collStart} onChange={(e) => setCollStart(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Collection End</label>
            <input type="datetime-local" value={collEnd} onChange={(e) => setCollEnd(e.target.value)} />
          </div>
        </div>

        <div className="form-group">
          <label>Delivery Deadline</label>
          <input type="datetime-local" value={deadline} onChange={(e) => setDeadline(e.target.value)} />
        </div>

        <div className="form-actions">
          <button className="btn" onClick={checkSvc} disabled={checking}>
            {checking ? 'Checking...' : 'Check Serviceability'}
          </button>
        </div>

        {svcResult && (
          <div style={{ marginTop: '1rem', padding: '0.75rem', background: svcResult.serviceable ? '#dcfce7' : '#fee2e2', borderRadius: 'var(--radius)' }}>
            <strong>{svcResult.serviceable ? '✓ Serviceable' : '✗ Not Serviceable'}</strong>
            {svcResult.reason && <p style={{ fontSize: '0.85rem', marginTop: '0.25rem' }}>{svcResult.reason}</p>}
            {svcResult.nearest_node_name && <p style={{ fontSize: '0.85rem' }}>Nearest node: {svcResult.nearest_node_name}</p>}
            {svcResult.serviceable && (
              <div style={{ marginTop: '0.75rem' }}>
                <button className="btn btn-primary" onClick={submit} disabled={submitting}>
                  {submitting ? 'Creating...' : 'Submit Request'}
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

