import React, { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import { api } from '../services/api';
import type { Sample, TimelineEntry, JourneyPlan } from '../types/models';

export default function SampleDetail() {
  const { id } = useParams<{ id: string }>();
  const [sample, setSample] = useState<Sample | null>(null);
  const [timeline, setTimeline] = useState<TimelineEntry[]>([]);
  const [journey, setJourney] = useState<JourneyPlan | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!id) return;
    Promise.all([
      api.readSampleLifecycle(id),
      api.readSampleState(id),
    ])
      .then(([lc, st]) => {
        setSample(st);
        setTimeline(lc.timeline || []);
        if (st.active_journey_id) {
          api.readJourneyPlan(st.active_journey_id).then(setJourney).catch(() => {});
        }
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed'))
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div className="loading">Loading sample...</div>;
  if (error) return <div className="error-msg">{error}</div>;
  if (!sample) return <div>Sample not found</div>;

  return (
    <div>
      <h1 className="page-title">Sample {sample.id?.slice(0, 12)}</h1>

      <div className="grid grid-2">
        <div className="card">
          <h3>Details</h3>
          <dl style={{ marginTop: '0.75rem', display: 'grid', gap: '0.25rem' }}>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Status</dt>
            <dd><span className={`badge badge-${sample.status === 'collected' ? 'active' : 'pending'}`}>{sample.status}</span></dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Type</dt>
            <dd>{sample.sample_type_name || sample.sample_type_id}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Container</dt>
            <dd>{sample.container_type || '-'}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Cooling Required</dt>
            <dd>{sample.requires_cooling ? 'Yes' : 'No'}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Origin</dt>
            <dd>{sample.origin_type} {sample.origin_address ? `- ${sample.origin_address}` : ''}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Deadline</dt>
            <dd>{sample.delivery_deadline ? new Date(sample.delivery_deadline).toLocaleString() : '-'}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Current Holder</dt>
            <dd>{sample.current_holder_name || 'None'} {sample.location_stale ? '(stale)' : ''}</dd>
            <dt style={{ fontWeight: 600, fontSize: '0.8rem', color: 'var(--text-muted)' }}>Last Update</dt>
            <dd>{sample.last_update ? new Date(sample.last_update).toLocaleString() : '-'}</dd>
          </dl>
        </div>

        <div className="card">
          <h3>Status Timeline</h3>
          <div className="status-timeline" style={{ marginTop: '0.75rem' }}>
            {timeline.map((e, i) => (
              <div key={i} className="timeline-entry">
                <div style={{ fontWeight: 600 }}>{e.status}</div>
                <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  {new Date(e.timestamp).toLocaleString()}
                </div>
                {e.location && <div style={{ fontSize: '0.85rem' }}>{e.location}</div>}
                {e.actor && <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>{e.actor}</div>}
              </div>
            ))}
            {timeline.length === 0 && <p style={{ color: 'var(--text-muted)' }}>No timeline entries</p>}
          </div>
        </div>
      </div>

      {journey && (
        <div className="card" style={{ marginTop: '1rem' }}>
          <h3>Journey Plan ({journey.status})</h3>
          <table style={{ marginTop: '0.75rem' }}>
            <thead>
              <tr>
                <th>#</th>
                <th>Location</th>
                <th>Action</th>
                <th>Assigned To</th>
                <th>Status</th>
                <th>Planned Arrival</th>
              </tr>
            </thead>
            <tbody>
              {journey.stops?.map((s) => (
                <tr key={s.id}>
                  <td>{s.sequence}</td>
                  <td>{s.location_name || s.location_id}</td>
                  <td>{s.action}</td>
                  <td>{s.assigned_name || '-'}</td>
                  <td><span className={`badge badge-${s.status === 'completed' ? 'completed' : 'pending'}`}>{s.status}</span></td>
                  <td>{s.planned_arrival ? new Date(s.planned_arrival).toLocaleString() : '-'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {sample.handling_checkpoints && sample.handling_checkpoints.length > 0 && (
        <div className="card" style={{ marginTop: '1rem' }}>
          <h3>Handling Checkpoints</h3>
          <table style={{ marginTop: '0.75rem' }}>
            <thead>
              <tr>
                <th>Time</th>
                <th>Container</th>
                <th>Temperature</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {sample.handling_checkpoints.map((cp) => (
                <tr key={cp.id}>
                  <td>{new Date(cp.recorded_at).toLocaleString()}</td>
                  <td>{cp.container_type}</td>
                  <td>{cp.temperature != null ? `${cp.temperature}°C` : '-'}</td>
                  <td>{cp.out_of_range ? <span className="badge badge-inactive">Out of Range</span> : <span className="badge badge-completed">OK</span>}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

