import { api } from '../services/api';
import type { Assignment, Sample, BootstrapData } from '../types/models';
import { useAuth } from '../hooks/useAuth';

export default function WorkList() {
  const { user } = useAuth();
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [samples, setSamples] = useState<Record<string, Sample>>({});
  const [bootstrap, setBootstrap] = useState<BootstrapData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [msg, setMsg] = useState('');
  const [workerLat, setWorkerLat] = useState('');
  const [workerLon, setWorkerLon] = useState('');
  const [checkpointSample, setCheckpointSample] = useState('');
  const [checkpointContainer, setCheckpointContainer] = useState('');
  const [checkpointTemp, setCheckpointTemp] = useState('');
  const [avail, setAvail] = useState(true);
  const [presealed, setPresealed] = useState({ sample_type_id: '', origin_type: 'clinic', origin_latitude: '', origin_longitude: '', origin_address: '', delivery_deadline: '' });

  const load = async () => {
    try {
      const [ass, bt] = await Promise.all([api.listRoleWork(), api.readBootstrap()]);
      setAssignments(ass || []);
      setBootstrap(bt);
      const sampleIds = [...new Set(ass.map((a) => a.sample_id).filter(Boolean))] as string[];
      if (sampleIds.length > 0) {
        const results = await Promise.all(sampleIds.map((id) => api.readSampleState(id).catch(() => null)));
        const map: Record<string, Sample> = {};
        results.forEach((s) => { if (s) map[s.id] = s; });
        setSamples(map);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const accept = async (assignmentId: string) => {
    try { await api.acceptAssignment(assignmentId); setMsg('Accepted'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const decline = async (assignmentId: string) => {
    try { await api.declineAssignment(assignmentId); setMsg('Declined'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const collectSeal = async (assignmentId: string, sampleId: string) => {
    try { await api.collectAndSealSample({ assignment_id: assignmentId, sample_id: sampleId }); setMsg('Collected & Sealed'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const recordLocation = async () => {
    try {
      await api.recordWorkerLocation(parseFloat(workerLat), parseFloat(workerLon));
      setMsg('Location recorded');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const toggleAvail = async () => {
    try { await api.setWorkerAvailability(!avail); setAvail(!avail); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const updateProgress = async (assignmentId: string, status: string) => {
    try { await api.updateAssignmentProgress({ assignment_id: assignmentId, status }); setMsg('Progress updated'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const recordCheckpoint = async () => {
    if (!checkpointSample) return;
    try {
      await api.recordHandlingCheckpoint({
        sample_id: checkpointSample,
        container_type: checkpointContainer,
        temperature: checkpointTemp ? parseFloat(checkpointTemp) : undefined,
      });
      setMsg('Checkpoint recorded');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

