import React, { useEffect, useState } from 'react';
import { api } from '../services/api';
import type { SampleType, BootstrapData } from '../types/models';

export default function AdminSampleTypes() {
  const [types, setTypes] = useState<SampleType[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [msg, setMsg] = useState('');

  const [name, setName] = useState('');
  const [containerType, setContainerType] = useState('standard');
  const [requiresCooling, setRequiresCooling] = useState(false);
  const [requiresQualified, setRequiresQualified] = useState(false);
  const [tempMin, setTempMin] = useState('');
  const [tempMax, setTempMax] = useState('');
  const [incompatible, setIncompatible] = useState('');

  const load = async () => {
    try {
      const bt = await api.readBootstrap();
      setTypes(bt.sample_types || []);
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); } finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const create = async () => {
    try {
      await api.createSampleType({
        name,
        container_type: containerType,
        requires_cooling: requiresCooling,
        requires_qualified_collector: requiresQualified,
        temperature_min: tempMin ? parseFloat(tempMin) : undefined,
        temperature_max: tempMax ? parseFloat(tempMax) : undefined,
        incompatible_with: incompatible ? incompatible.split(',').map((s) => s.trim()) : undefined,
      });
      setMsg('Sample type created'); load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div>
      <h1 className="page-title">Manage Sample Types</h1>
      {error && <div className="error-msg">{error}</div>}
      {msg && <div className="success-msg">{msg}</div>}

      <div className="card" style={{ marginBottom: '1rem', maxWidth: 600 }}>
        <h3>Create Sample Type</h3>
        <div className="grid grid-2">
          <div className="form-group">
            <label>Name</label>
            <input value={name} onChange={(e) => setName(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Container Type</label>
            <select value={containerType} onChange={(e) => setContainerType(e.target.value)}>
              <option value="standard">Standard</option>
              <option value="cooled">Cooled</option>
              <option value="insulated">Insulated</option>
              <option value="biohazard">Biohazard</option>
            </select>
          </div>
          <div className="form-group">
            <label>Temperature Min (°C)</label>
            <input type="number" step="any" value={tempMin} onChange={(e) => setTempMin(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Temperature Max (°C)</label>
            <input type="number" step="any" value={tempMax} onChange={(e) => setTempMax(e.target.value)} />
          </div>
        </div>
        <div className="form-group">
          <label>Incompatible With (comma-separated sample type names)</label>
          <input value={incompatible} onChange={(e) => setIncompatible(e.target.value)} />
        </div>
        <div className="form-group" style={{ display: 'flex', gap: '1.5rem' }}>
          <label style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
            <input type="checkbox" checked={requiresCooling} onChange={(e) => setRequiresCooling(e.target.checked)} />
            Requires Cooling
          </label>
          <label style={{ display: 'flex', alignItems: 'center', gap: '0.25rem' }}>
            <input type="checkbox" checked={requiresQualified} onChange={(e) => setRequiresQualified(e.target.checked)} />
            Requires Qualified Collector
          </label>
        </div>
        <button className="btn btn-primary" onClick={create}>Create Sample Type</button>
      </div>

      <div className="card">
        <h3>Sample Types ({types.length})</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>Name</th><th>Container</th><th>Cooling</th><th>Qualified</th><th>Temp Range</th><th>Incompatible</th></tr>
          </thead>
          <tbody>
            {types.map((st) => (
              <tr key={st.id}>
                <td><strong>{st.name}</strong></td>
                <td>{st.container_type}</td>
                <td>{st.requires_cooling ? 'Yes' : 'No'}</td>
                <td>{st.requires_qualified_collector ? 'Yes' : 'No'}</td>
                <td>{st.temperature_min != null ? `${st.temperature_min}-${st.temperature_max}°C` : '-'}</td>
                <td>{st.incompatible_with?.join(', ') || '-'}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

