import React, { useState } from 'react';
import { api } from '../services/api';
import type { AuditEntry } from '../types/models';

export default function AuditSearch() {
  const [userId, setUserId] = useState('');
  const [action, setAction] = useState('');
  const [entityType, setEntityType] = useState('');
  const [entityId, setEntityId] = useState('');
  const [results, setResults] = useState<AuditEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const search = async () => {
    setLoading(true);
    setError('');
    const params: Record<string, string> = {};
    if (userId) params.user_id = userId;
    if (action) params.action = action;
    if (entityType) params.entity_type = entityType;
    if (entityId) params.entity_id = entityId;

    try {
      const r = await api.searchAuditTrail(params);
      setResults(r || []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h1 className="page-title">Audit Search</h1>
      {error && <div className="error-msg">{error}</div>}

      <div className="card" style={{ marginBottom: '1rem' }}>
        <div className="grid grid-2">
          <div className="form-group">
            <label>User ID</label>
            <input value={userId} onChange={(e) => setUserId(e.target.value)} placeholder="Filter by user" />
          </div>
          <div className="form-group">
            <label>Action</label>
            <input value={action} onChange={(e) => setAction(e.target.value)} placeholder="e.g., login, collect, handoff" />
          </div>
          <div className="form-group">
            <label>Entity Type</label>
            <select value={entityType} onChange={(e) => setEntityType(e.target.value)}>
              <option value="">All</option>
              <option value="sample">Sample</option>
              <option value="journey">Journey</option>
              <option value="request">Request</option>
              <option value="user">User</option>
              <option value="location">Location</option>
              <option value="assignment">Assignment</option>
              <option value="handoff">Handoff</option>
              <option value="capacity">Capacity</option>
            </select>
          </div>
          <div className="form-group">
            <label>Entity ID</label>
            <input value={entityId} onChange={(e) => setEntityId(e.target.value)} placeholder="Specific entity" />
          </div>
        </div>
        <button className="btn btn-primary" onClick={search} disabled={loading}>
          {loading ? 'Searching...' : 'Search'}
        </button>
      </div>

      <div className="card">
        <h3>Results ({results.length})</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>Time</th><th>User</th><th>Role</th><th>Action</th><th>Entity</th><th>Success</th><th>Details</th></tr>
          </thead>
          <tbody>
            {results.map((e) => (
              <tr key={e.id}>
                <td>{new Date(e.timestamp).toLocaleString()}</td>
                <td>{e.user_id}</td>
                <td>{e.role?.replace(/_/g, ' ')}</td>
                <td>{e.action}</td>
                <td>{e.entity_type} <code>{e.entity_id?.slice(0, 8)}</code></td>
                <td>{e.success ? <span className="badge badge-completed">OK</span> : <span className="badge badge-inactive">Failed</span>}</td>
                <td style={{ fontSize: '0.8rem', maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis' }}>
                  {e.details ? JSON.stringify(e.details) : '-'}
                </td>
              </tr>
            ))}
            {results.length === 0 && <tr><td colSpan={7} style={{ color: 'var(--text-muted)', textAlign: 'center' }}>No results</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}

