    12	func haversine(lat1, lon1, lat2, lon2 float64) float64 {
    13		const R = 6371.0
    14		dLat := (lat2 - lat1) * 0.017453292519943295
    15		dLon := (lon2 - lon1) * 0.017453292519943295
    16		a := math.Pow(math.Sin(dLat/2), 2) + math.Cos(lat1*0.017453292519943295)*math.Cos(lat2*0.017453292519943295)*math.Pow(math.Sin(dLon/2), 2)
    17		return R * 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    18	}
