observation.old_content:
package main

import (
	"fmt"
	"log"
	"net/http"
	"os"

	"github.com/lab-sample-pickup-delivery/backend/internal/auth"
	"github.com/lab-sample-pickup-delivery/backend/internal/config"
	"github.com/lab-sample-pickup-delivery/backend/internal/db"
	"github.com/lab-sample-pickup-delivery/backend/internal/handlers"
	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
)

func main() {
	cfg := config.Load()
	pg, err := db.New(cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("database: %v", err)
	}
	defer pg.Close()

	if err := pg.RunMigrations(); err != nil {
		log.Fatalf("migrate: %v", err)
	}

	authStore := auth.New(pg.DB)
	if cfg.AdminUsername != "" && cfg.AdminPassword != "" {
		if err := authStore.EnsureAdmin(cfg.AdminUsername, cfg.AdminPassword); err != nil {
			log.Printf("ensure admin: %v", err)
		}
	}

	h := handlers.New(pg.DB, authStore)

	mux := http.NewServeMux()

	// Public endpoints
	mux.HandleFunc("/ready", h.SystemReadiness)

	// Auth bypasses auth middleware
	ah := &handlers.AuthHandler{DB: pg.DB, AuthStore: authStore}
	mux.HandleFunc("/api/auth/login", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusMethodNotAllowed)
			fmt.Fprint(w, `{"error":"Method not allowed"}`)
			return
		}
		ah.AuthenticateUser(w, r)
	})

	// Serve static frontend files
	frontendDir := os.Getenv("FRONTEND_DIR")
	if frontendDir == "" {
		frontendDir = "../dist"
	}
	frontFS := http.FileServer(http.Dir(frontendDir))
	mux.Handle("/", frontFS)

	// Protected API
	api := http.NewServeMux()
	setupAPIRoutes(api, h, pg, authStore)

	protected := middleware.AuthMiddleware(authStore)(api)

	// Mount API
	mux.Handle("/api/", protected)

	// CORS
	handler := middleware.CORS(mux)

	addr := fmt.Sprintf(":%s", cfg.Port)
	log.Printf("Starting server on %s", addr)
	if err := http.ListenAndServe(addr, handler); err != nil {
		log.Fatalf("server: %v", err)
	}
}

func setupAPIRoutes(mux *http.ServeMux, h *handlers.Handler, pg *db.DB, authStore *auth.AuthStore) {
	ah := &handlers.AuthHandler{DB: pg.DB, AuthStore: authStore}

	mux.HandleFunc("/api/auth/login", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		ah.AuthenticateUser(w, r)
	})

	mux.HandleFunc("/api/auth/select-role", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		ah.SelectActiveRole(w, r)
	})

	mux.HandleFunc("/api/read-bootstrap", func(w http.ResponseWriter, r *http.Request) {
		ah.ReadUIBootstrap(w, r)
	})

	mux.HandleFunc("/api/check-serviceability", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.CheckServiceability(w, r)
	})

	mux.HandleFunc("/api/create-collection-request", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.CreateCollectionRequest(w, r)
	})

	mux.HandleFunc("/api/ingest-presealed-sample", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.IngestPresealedSample(w, r)
	})

	mux.HandleFunc("/api/collect-and-seal-sample", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.CollectAndSealSample(w, r)
	})

	mux.HandleFunc("/api/list-role-work", h.ListRoleWork)

	mux.HandleFunc("/api/accept-assignment", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.AcceptAssignment(w, r)
	})

	mux.HandleFunc("/api/decline-assignment", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.DeclineAssignment(w, r)
	})

	mux.HandleFunc("/api/record-worker-location", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.RecordWorkerLocation(w, r)
	})

	mux.HandleFunc("/api/update-assignment-progress", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.UpdateAssignmentProgress(w, r)
	})

	mux.HandleFunc("/api/set-worker-availability", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.SetWorkerAvailability(w, r)
	})

	mux.HandleFunc("/api/initiate-handoff", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.InitiateHandoff(w, r)
	})

	mux.HandleFunc("/api/confirm-handoff", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.ConfirmHandoff(w, r)
	})

	mux.HandleFunc("/api/confirm-laboratory-receipt", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.ConfirmLaboratoryReceipt(w, r)
	})

	mux.HandleFunc("/api/record-laboratory-exception", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.RecordLaboratoryException(w, r)
	})

	mux.HandleFunc("/api/record-handling-checkpoint", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.RecordHandlingCheckpoint(w, r)
	})

	mux.HandleFunc("/api/read-sample-state/", h.ReadSampleState)

	mux.HandleFunc("/api/read-sample-lifecycle", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.ReadSampleLifecycle(w, r)
	})

	mux.HandleFunc("/api/read-operations-state", h.ReadOperationsState)

	mux.HandleFunc("/api/read-journey-plan", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.ReadJourneyPlan(w, r)
	})

	mux.HandleFunc("/api/read-serviceability-snapshot", h.ReadServiceabilitySnapshot)

	mux.HandleFunc("/api/cancel-journey", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.CancelJourney(w, r)
	})

	mux.HandleFunc("/api/reroute-journey", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.RerouteJourney(w, r)
	})

	mux.HandleFunc("/api/split-journey", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.SplitJourney(w, r)
	})

	mux.HandleFunc("/api/merge-journeys", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		h.MergeJourneys(w, r)
	})

	mux.HandleFunc("/api/edit-active-plan", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
