	"github.com/lab-sample-pickup-delivery/backend/internal/handlers"
	"github.com/lab-sample-pickup-delivery/backend/internal/middleware"
)

func main() {
	cfg := config.Load()
	pg, err := db.New(cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("database: %v", err)
	}
	defer pg.Close()

	if err := pg.RunMigrations(); err != nil {
		log.Fatalf("migrate: %v", err)
	}

	authStore := auth.New(pg.DB)
	if cfg.AdminUsername != "" && cfg.AdminPassword != "" {
		if err := authStore.EnsureAdmin(cfg.AdminUsername, cfg.AdminPassword); err != nil {
			log.Printf("ensure admin: %v", err)
		}
	}

	h := handlers.New(pg.DB, authStore)

	mux := http.NewServeMux()

	// Public endpoints
	mux.HandleFunc("/ready", h.SystemReadiness)

	// Auth bypasses auth middleware
	ah := &handlers.AuthHandler{DB: pg.DB, AuthStore: authStore}
	mux.HandleFunc("/api/authenticate-user", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			middleware.WriteError(w, 405, "Method not allowed", "method_not_allowed")
			return
		}
		ah.AuthenticateUser(w, r)
	})

	// Serve static frontend files
	frontendDir := os.Getenv("FRONTEND_DIR")
	if frontendDir == "" {
		frontendDir = "../dist"
	}
	frontFS := http.FileServer(http.Dir(frontendDir))
	mux.Handle("/", frontFS)

	// Protected API
	api := http.NewServeMux()
	setupAPIRoutes(api, h, pg, authStore)

	protected := middleware.AuthMiddleware(authStore)(api)

	// Mount API
	mux.Handle("/api/", protected)

	// CORS
	handler := middleware.CORS(mux)

	addr := fmt.Sprintf(":%s", cfg.Port)
	log.Printf("Starting server on %s", addr)
	if err := http.ListenAndServe(addr, handler); err != nil {
		log.Fatalf("server: %v", err)
	}
}

func setupAPIRoutes(mux *http.ServeMux, h *handlers.Handler, pg *db.DB, authStore *auth.AuthStore) {
	ah := &handlers.AuthHandler{DB: pg.DB, AuthStore: authStore}

	mux.HandleFunc("/api/auth/login", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", 405)
			return
		}
		ah.AuthenticateUser(w, r)
	})

