import type {
  User,
  AuthResponse,
  BootstrapData,
  ServiceabilityRequest,
  ServiceabilityResponse,
  CollectionRequest,
  Sample,
  JourneyPlan,
  Assignment,
  OperationsState,
  AuditEntry,
  TimelineEntry,
  CreateUserRequest,
  Location,
  Connection,
  SampleType,
  ExceptionInfo,
} from '../types/models';

const BASE = '/api';

function token(): string | null {
  return localStorage.getItem('token');
}

async function request<T>(path: string, opts: RequestInit = {}): Promise<T> {
  const t = token();
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (t) headers['Authorization'] = `Bearer ${t}`;
  if (opts.headers) {
    const h = opts.headers as Record<string, string>;
    Object.assign(headers, h);
  }

  const res = await fetch(BASE + path, { ...opts, headers });
  if (!res.ok) {
    const body = await res.text();
    let msg = body;
    try {
      const j = JSON.parse(body);
      msg = j.error || j.message || body;
    } catch {
      /* use raw body */
    }
    throw new Error(msg || `${res.status}`);
  }
  return res.json() as Promise<T>;
}

export const api = {
  // Auth
  login(username: string, password: string): Promise<AuthResponse> {
    return request<AuthResponse>('/auth/login', {
      method: 'POST',
      body: JSON.stringify({ username, password }),
    });
  },

  selectRole(role: string): Promise<User> {
    return request<User>('/select-active-role', {
      method: 'PUT',
      body: JSON.stringify({ role }),
    });
  },

  readUser(): Promise<User> {
    return request<User>('/read-user');
  },

  // Bootstrap
  readBootstrap(): Promise<BootstrapData> {
    return request<BootstrapData>('/read-bootstrap');
  },

  // Serviceability
  checkServiceability(data: ServiceabilityRequest): Promise<ServiceabilityResponse> {
    return request<ServiceabilityResponse>('/check-serviceability', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  readServiceabilitySnapshot(): Promise<{ version: number; calculated_at: string; regions: unknown[] }> {
    return request('/read-serviceability-snapshot');
  },

  // Requests
  createCollectionRequest(data: CollectionRequest): Promise<{ request_id: string; sample_id: string; journey_id: string }> {
    return request('/create-collection-request', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  ingestPresealedSample(data: Record<string, unknown>): Promise<{ sample_id: string; journey_id: string }> {
    return request('/ingest-presealed-sample', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  // Samples
  readSampleState(sampleId: string): Promise<Sample> {
    return request(`/read-sample-state?sample_id=${encodeURIComponent(sampleId)}`);
  },

  readSampleLifecycle(sampleId: string): Promise<{ sample: Sample; timeline: TimelineEntry[] }> {
    return request(`/read-sample-lifecycle?sample_id=${encodeURIComponent(sampleId)}`);
  },

  recordHandlingCheckpoint(data: { sample_id: string; container_type: string; temperature?: number }): Promise<void> {
    return request('/record-handling-checkpoint', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  // Journeys
  readJourneyPlan(journeyId: string): Promise<JourneyPlan> {
    return request(`/read-journey-plan?journey_id=${encodeURIComponent(journeyId)}`);
  },

  cancelJourney(journeyId: string, reason?: string): Promise<void> {
    return request('/cancel-journey', {
      method: 'POST',
      body: JSON.stringify({ journey_id: journeyId, reason }),
    });
  },

  rerouteJourney(journeyId: string, newStops: unknown[]): Promise<JourneyPlan> {
    return request('/reroute-journey', {
      method: 'POST',
      body: JSON.stringify({ journey_id: journeyId, new_stops: newStops }),
    });
  },

  splitJourney(journeyId: string, splitAfterStopIndex: number): Promise<{ original: JourneyPlan; new: JourneyPlan }> {
    return request('/split-journey', {
      method: 'POST',
      body: JSON.stringify({ journey_id: journeyId, split_after_stop_index: splitAfterStopIndex }),
    });
  },

  mergeJourneys(journeyIds: string[]): Promise<JourneyPlan> {
    return request('/merge-journeys', {
      method: 'POST',
      body: JSON.stringify({ journey_ids: journeyIds }),
    });
  },

  editActivePlan(journeyId: string, version: number, changes: unknown): Promise<JourneyPlan> {
    return request('/edit-active-plan', {
      method: 'PUT',
      body: JSON.stringify({ journey_id: journeyId, version, changes }),
    });
  },

  reportDisruption(data: { element_type: string; element_id: string; description: string }): Promise<ExceptionInfo> {
    return request('/report-disruption', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  // Ops
  readOperationsState(): Promise<OperationsState> {
    return request('/read-operations-state');
  },

  searchAuditTrail(params: Record<string, string>): Promise<AuditEntry[]> {
    const qs = new URLSearchParams(params).toString();
    return request(`/search-audit-trail?${qs}`);
  },

