    17	  const [checkpointContainer, setCheckpointContainer] = useState('');
    18	  const [checkpointTemp, setCheckpointTemp] = useState('');
    19	  const [avail, setAvail] = useState(true);
    20	  const [presealed, setPresealed] = useState({ sample_type_id: '', origin_type: 'clinic', origin_latitude: '', origin_longitude: '', origin_address: '', delivery_deadline: '' });
    21	
    22	  const load = async () => {
