    31	        results.forEach((s) => { if (s) map[s.id] = s; });
    32	        setSamples(map);
    33	      }
    34	    } catch (err) {
    35	      setError(err instanceof Error ? err.message : 'Failed');
    36	    } finally {
    37	      setLoading(false);
    38	    }
    39	  };
    40	
    41	  useEffect(() => { load(); }, []);
    42	
