    44	    try { await api.acceptAssignment(assignmentId); setMsg('Accepted'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    45	  };
    46	
    47	  const decline = async (assignmentId: string) => {
    48	    try { await api.declineAssignment(assignmentId); setMsg('Declined'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    49	  };
