    53	  };
    54	
    55	  const recordLocation = async () => {
    56	    try {
    57	      await api.recordWorkerLocation(parseFloat(workerLat), parseFloat(workerLon));
    58	      setMsg('Location recorded');
    59	    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    60	  };
    61	
    62	  const toggleAvail = async () => {
    63	    try { await api.setWorkerAvailability(!avail); setAvail(!avail); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    64	  };
    65	
    66	  const updateProgress = async (assignmentId: string, status: string) => {
    67	    try { await api.updateAssignmentProgress({ assignmentId, status }); setMsg('Progress updated'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    68	  };
    69	
    70	  const recordCheckpoint = async () => {
    71	    if (!checkpointSample) return;
    72	    try {
    73	      await api.recordHandlingCheckpoint({
    74	        sampleId: checkpointSample,
    75	        containerType: checkpointContainer,
    76	        temperature: checkpointTemp ? parseFloat(checkpointTemp) : undefined,
    77	      });
    78	      setMsg('Checkpoint recorded');
    79	    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    80	  };
    81	
    82	  const ingestPresealed = async () => {
    83	    try {
    84	      await api.ingestPresealedSample(presealed);
    85	      setMsg('Pre-sealed sample registered');
    86	      setPresealed({ sample_type_id: '', origin_type: 'clinic', origin_latitude: '', origin_longitude: '', origin_address: '', delivery_deadline: '' });
    87	    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    88	  };
    89	
    90	  if (loading) return <div className="loading">Loading work...</div>;
    91	
    92	  const isCCP = user?.active_role === 'certified_collection_professional';
    93	  const isCourier = user?.active_role === 'relay_courier';
    94	  const isHandler = user?.active_role === 'node_handler';
