   101	      {msg && <div className="success-msg">{msg}</div>}
   102	
   103	      <div className="grid grid-2" style={{ marginBottom: '1rem' }}>
   104	        <div className="card">
   105	          <h3>My Location</h3>
   106	          <div className="grid grid-2">
   107	            <div className="form-group">
   108	              <label>Latitude</label>
