   110	            </div>
   111	            <div className="form-group">
   112	              <label>Longitude</label>
   113	              <input type="number" step="any" value={workerLon} onChange={(e) => setWorkerLon(e.target.value)} />
   114	            </div>
   115	          </div>
   116	          <button className="btn btn-primary" onClick={recordLocation}>Record Location</button>
   117	        </div>
   118	
   119	        <div className="card">
   120	          <h3>Availability</h3>
   121	          <button className={`btn ${avail ? 'btn-success' : 'btn-danger'}`} onClick={toggleAvail}>
   122	            {avail ? 'Available' : 'Unavailable'}
   123	          </button>
   124	        </div>
   125	      </div>
   126	
   127	      {isCCP && (
   128	        <div className="card" style={{ marginBottom: '1rem' }}>
   129	          <h3>Record Handling Checkpoint</h3>
   130	          <div className="grid grid-3">
   131	            <div className="form-group">
   132	              <label>Sample ID</label>
   133	              <input value={checkpointSample} onChange={(e) => setCheckpointSample(e.target.value)} />
   134	            </div>
   135	            <div className="form-group">
   136	              <label>Container Type</label>
   137	              <input value={checkpointContainer} onChange={(e) => setCheckpointContainer(e.target.value)} />
   138	            </div>
   139	            <div className="form-group">
   140	              <label>Temperature (°C)</label>
   141	              <input type="number" step="any" value={checkpointTemp} onChange={(e) => setCheckpointTemp(e.target.value)} />
   142	            </div>
   143	          </div>
   144	          <button className="btn btn-primary" onClick={recordCheckpoint}>Record Checkpoint</button>
   145	        </div>
   146	      )}
   147	
   148	      {(isCCP || isCourier || isHandler || isLabOp) && (
   149	        <div className="card" style={{ marginBottom: '1rem' }}>
   150	          <h3>Ingest Pre-sealed Sample</h3>
   151	          <div className="grid grid-2">
   152	            <div className="form-group">
   153	              <label>Origin Type</label>
   154	              <select value={presealed.origin_type} onChange={(e) => setPresealed({ ...presealed, origin_type: e.target.value })}>
   155	                <option value="clinic">Clinic</option>
   156	                <option value="node">Collection Node</option>
   157	              </select>
   158	            </div>
   159	            <div className="form-group">
   160	              <label>Sample Type</label>
   161	              <select value={presealed.sample_type_id} onChange={(e) => setPresealed({ ...presealed, sample_type_id: e.target.value })}>
   162	                <option value="">-- Select --</option>
   163	                {bootstrap?.sample_types?.map((st) => (
   164	                  <option key={st.id} value={st.id}>{st.name}</option>
   165	                ))}
   166	              </select>
   167	            </div>
   168	            <div className="form-group">
   169	              <label>Latitude</label>
   170	              <input type="number" step="any" value={presealed.origin_latitude} onChange={(e) => setPresealed({ ...presealed, origin_latitude: e.target.value })} />
   171	            </div>
   172	            <div className="form-group">
   173	              <label>Longitude</label>
   174	              <input type="number" step="any" value={presealed.origin_longitude} onChange={(e) => setPresealed({ ...presealed, origin_longitude: e.target.value })} />
