   177	              <label>Address</label>
   178	              <input value={presealed.origin_address} onChange={(e) => setPresealed({ ...presealed, origin_address: e.target.value })} />
   179	            </div>
   180	            <div className="form-group">
   181	              <label>Delivery Deadline</label>
   182	              <input type="datetime-local" value={presealed.delivery_deadline} onChange={(e) => setPresealed({ ...presealed, delivery_deadline: e.target.value })} />
   183	            </div>
   184	          </div>
   185	          <button className="btn btn-primary" onClick={ingestPresealed} style={{ marginTop: '0.5rem' }}>Register</button>
   186	        </div>
   187	      )}
   188	
   189	      <div className="card">
   190	        <h3>Assignments ({assignments.length})</h3>
   191	        {assignments.length === 0 ? (
   192	          <p style={{ color: 'var(--text-muted)', marginTop: '0.5rem' }}>No assignments</p>
   193	        ) : (
   194	          <table style={{ marginTop: '0.75rem' }}>
   195	            <thead>
   196	              <tr>
   197	                <th>ID</th>
   198	                <th>Sample</th>
   199	                <th>Action</th>
   200	                <th>From</th>
   201	                <th>To</th>
   202	                <th>Status</th>
   203	                <th>Actions</th>
   204	              </tr>
   205	            </thead>
   206	            <tbody>
   207	              {assignments.map((a) => (
   208	                <tr key={a.id}>
   209	                  <td><code>{a.id?.slice(0, 8)}</code></td>
   210	                  <td><code>{a.sample_id?.slice(0, 8)}</code></td>
   211	                  <td>{a.action}</td>
