   218	                        <>
   219	                          <button className="btn btn-success" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => accept(a.id)}>Accept</button>
   220	                          <button className="btn btn-danger" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => decline(a.id)}>Decline</button>
   221	                        </>
   222	                      )}
   223	                      {a.status === 'accepted' && isCCP && a.action === 'collect' && a.sample_id && (
   224	                        <button className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => collectSeal(a.id, a.sample_id!)}>Collect & Seal</button>
   225	                      )}
   226	                      {a.status === 'accepted' && (isCourier || isHandler) && (
   227	                        <button className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => updateProgress(a.id, 'in_transit')}>Start Transit</button>
   228	                      )}
   229	                      {a.status === 'accepted' && isLabOp && a.action === 'receive' && a.sample_id && (
   230	                        <button className="btn btn-success" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={async () => { await api.confirmLaboratoryReceipt(a.sample_id!, a.sample_id!); load(); }}>Confirm Receipt</button>
   231	                      )}
   232	                    </div>
   233	                  </td>
   234	                </tr>
   235	              ))}
   236	            </tbody>
   237	          </table>
   238	        )}
   239	      </div>
   240	    </div>
   241	  );
   242	}

