  },

  recordWorkerLocation(latitude: number, longitude: number): Promise<{ workerId: string; location: { latitude: number; longitude: number }; recordedAt: string }> {
    return request('/record-worker-location', {
      method: 'POST',
      body: JSON.stringify({
        location: { latitude, longitude },
        recordedAt: new Date().toISOString(),
      }),
    });
  },

  updateAssignmentProgress(data: { assignmentId: string; status: string }): Promise<{ assignmentId: string; sampleId: string; status: string }> {
    return request('/update-assignment-progress', {
      method: 'POST',
      body: JSON.stringify({
        assignmentId: data.assignmentId,
        status: data.status,
        occurredAt: new Date().toISOString(),
        idempotencyKey: crypto.randomUUID(),
      }),
    });
  },

  setWorkerAvailability(available: boolean): Promise<{ workerId: string; available: boolean; capacityUnits: number }> {
    return request('/set-worker-availability', {
      method: 'POST',
      body: JSON.stringify({ available, capacityUnits: 1 }),
    });
  },

  // Handoffs
  initiateHandoff(
    sampleId: string,
    receiverId: string,
    fromAssignmentId?: string,
    toAssignmentId?: string,
  ): Promise<HandoffInfo> {
    return request('/initiate-handoff', {
      method: 'POST',
      body: JSON.stringify({
        sampleId,
        receiverId,
        fromAssignmentId,
        toAssignmentId,
        idempotencyKey: crypto.randomUUID(),
      }),
    });
  },

  confirmHandoff(handoffId: string, confirmationSide: 'sender' | 'receiver'): Promise<HandoffInfo> {
    return request('/confirm-handoff', {
      method: 'POST',
      body: JSON.stringify({
        handoffId,
        confirmationSide,
        confirmedAt: new Date().toISOString(),
        idempotencyKey: crypto.randomUUID(),
      }),
    });
  },

  confirmLaboratoryReceipt(sampleId: string, laboratoryId: string): Promise<{ sampleId: string; laboratoryId: string; status: string }> {
    return request('/confirm-laboratory-receipt', {
      method: 'POST',
      body: JSON.stringify({
        sampleId,
        laboratoryId,
        receivedAt: new Date().toISOString(),
        idempotencyKey: crypto.randomUUID(),
      }),
    });
  },

  recordLaboratoryException(sampleId: string, exceptionType: string, description: string): Promise<void> {
    return request('/record-laboratory-exception', {
      method: 'POST',
      body: JSON.stringify({ sampleId, exceptionType, description }),
    });
  },

  // Admin
  createUser(data: CreateUserRequest): Promise<User> {
    return request('/create-user', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  updateUserAccess(userId: string, data: Record<string, unknown>): Promise<User> {
    return request('/update-user-access', {
      method: 'POST',
      body: JSON.stringify({ userId, ...data }),
    });
  },

  readUser(userId: string): Promise<User> {
    return request(`/read-user/${encodeURIComponent(userId)}`);
  },

  createLocation(data: Record<string, unknown>): Promise<Location> {
    return request('/create-location', {
      method: 'POST',
      body: JSON.stringify(data),
    });
  },

