      method: 'POST',
      body: JSON.stringify(data),
    });
  },

  setConnectionStatus(connectionId: string, active: boolean): Promise<void> {
    return request('/set-connection-status', {
      method: 'POST',
      body: JSON.stringify({ connectionId, active }),
