import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api } from '../services/api';
import type { Sample } from '../types/models';
import { useAuth } from '../hooks/useAuth';

export default function Dashboard() {
  const { user } = useAuth();
  const [samples, setSamples] = useState<Sample[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (user?.active_role === 'requester') {
      api.listRoleWork()
        .then(async (assignments) => {
          const ids = [...new Set(assignments.map((a: { sample_id?: string }) => a.sample_id).filter(Boolean))] as string[];
          const sampleData = await Promise.all(ids.map((id: string) => api.readSampleState(id)));
          setSamples(sampleData);
        })
        .catch(() => {})
        .finally(() => setLoading(false));
    } else {
      api.readOperationsState()
        .then((state) => setSamples(state.samples || []))
        .catch(() => {})
        .finally(() => setLoading(false));
    }
  }, [user?.active_role]);

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div>
      <h1 className="page-title">Dashboard</h1>

      <div className="grid grid-2">
        <div className="card">
          <h3>Quick Actions</h3>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', marginTop: '0.75rem' }}>
            {user?.active_role === 'requester' && (
              <Link to="/new-request" className="btn btn-primary">New Collection Request</Link>
            )}
            <Link to="/work" className="btn">View My Work</Link>
          </div>
        </div>

        <div className="card">
          <h3>Role: {user?.active_role?.replace(/_/g, ' ')}</h3>
          <p style={{ color: 'var(--text-muted)', marginTop: '0.5rem' }}>
            {user?.roles?.length ?? 0} roles assigned
          </p>
        </div>
      </div>

      {samples.length > 0 && (
        <div style={{ marginTop: '2rem' }}>
          <h2 style={{ marginBottom: '0.75rem' }}>Samples</h2>
          <table>
            <thead>
              <tr>
                <th>Sample ID</th>
                <th>Type</th>
                <th>Status</th>
                <th>Current Holder</th>
                <th>Last Update</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {samples.map((s) => (
                <tr key={s.id}>
                  <td><code>{s.id?.slice(0, 8)}</code></td>
                  <td>{s.sample_type_name || s.sample_type_id}</td>
                  <td><span className={`badge badge-${s.status === 'collected' ? 'active' : 'pending'}`}>{s.status}</span></td>
                  <td>{s.current_holder_name || '-'}</td>
                  <td>{s.last_update ? new Date(s.last_update).toLocaleString() : '-'}</td>
                  <td><Link to={`/samples/${s.id}`}>View</Link></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

