            <div className="form-group">
              <label>Latitude</label>
              <input type="number" step="any" value={workerLat} onChange={(e) => setWorkerLat(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Longitude</label>
              <input type="number" step="any" value={workerLon} onChange={(e) => setWorkerLon(e.target.value)} />
            </div>
          </div>
          <button className="btn btn-primary" onClick={recordLocation}>Record Location</button>
        </div>

        <div className="card">
          <h3>Availability</h3>
          <button className={`btn ${avail ? 'btn-success' : 'btn-danger'}`} onClick={toggleAvail}>
            {avail ? 'Available' : 'Unavailable'}
          </button>
        </div>
      </div>

      {isCCP && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h3>Record Handling Checkpoint</h3>
          <div className="grid grid-3">
            <div className="form-group">
              <label>Sample ID</label>
              <input value={checkpointSample} onChange={(e) => setCheckpointSample(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Container Type</label>
              <input value={checkpointContainer} onChange={(e) => setCheckpointContainer(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Temperature (°C)</label>
              <input type="number" step="any" value={checkpointTemp} onChange={(e) => setCheckpointTemp(e.target.value)} />
            </div>
          </div>
          <button className="btn btn-primary" onClick={recordCheckpoint}>Record Checkpoint</button>
        </div>
      )}

      {(isCCP || isCourier || isHandler || isLabOp) && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h3>Ingest Pre-sealed Sample</h3>
          <div className="grid grid-2">
            <div className="form-group">
              <label>Origin Type</label>
              <select value={presealed.origin_type} onChange={(e) => setPresealed({ ...presealed, origin_type: e.target.value })}>
                <option value="clinic">Clinic</option>
                <option value="node">Collection Node</option>
              </select>
            </div>
            <div className="form-group">
              <label>Sample Type</label>
              <select value={presealed.sample_type_id} onChange={(e) => setPresealed({ ...presealed, sample_type_id: e.target.value })}>
                <option value="">-- Select --</option>
                {bootstrap?.sample_types?.map((st) => (
                  <option key={st.id} value={st.id}>{st.name}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label>Latitude</label>
              <input type="number" step="any" value={presealed.origin_latitude} onChange={(e) => setPresealed({ ...presealed, origin_latitude: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Longitude</label>
              <input type="number" step="any" value={presealed.origin_longitude} onChange={(e) => setPresealed({ ...presealed, origin_longitude: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Address</label>
              <input value={presealed.origin_address} onChange={(e) => setPresealed({ ...presealed, origin_address: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Delivery Deadline</label>
              <input type="datetime-local" value={presealed.delivery_deadline} onChange={(e) => setPresealed({ ...presealed, delivery_deadline: e.target.value })} />
            </div>
          </div>
          <button className="btn btn-primary" onClick={ingestPresealed} style={{ marginTop: '0.5rem' }}>Register</button>
        </div>
      )}

      <div className="card">
        <h3>Assignments ({assignments.length})</h3>
        {assignments.length === 0 ? (
          <p style={{ color: 'var(--text-muted)', marginTop: '0.5rem' }}>No assignments</p>
        ) : (
          <table style={{ marginTop: '0.75rem' }}>
            <thead>
              <tr>
                <th>ID</th>
                <th>Sample</th>
                <th>Action</th>
                <th>From</th>
                <th>To</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {assignments.map((a) => (
                <tr key={a.id}>
                  <td><code>{a.id?.slice(0, 8)}</code></td>
                  <td><code>{a.sample_id?.slice(0, 8)}</code></td>
                  <td>{a.action}</td>
                  <td>{a.location_from || '-'}</td>
                  <td>{a.location_to || '-'}</td>
                  <td><span className={`badge badge-${a.status === 'accepted' ? 'active' : 'pending'}`}>{a.status}</span></td>
                  <td>
                    <div style={{ display: 'flex', gap: '0.25rem' }}>
                      {a.status === 'offered' && (
                        <>
                          <button className="btn btn-success" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => accept(a.id)}>Accept</button>
                          <button className="btn btn-danger" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => decline(a.id)}>Decline</button>
                        </>
                      )}
                      {a.status === 'accepted' && isCCP && a.action === 'collect' && a.sample_id && (
                        <button className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => collectSeal(a.id, a.sample_id!)}>Collect & Seal</button>
                      )}
                      {a.status === 'accepted' && (isCourier || isHandler) && (
                        <button className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => updateProgress(a.id, 'in_transit')}>Start Transit</button>
                      )}
                      {a.status === 'accepted' && isLabOp && a.action === 'receive' && a.sample_id && (
                        <button className="btn btn-success" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={async () => { await api.confirmLaboratoryReceipt(a.sample_id!, a.sample_id!); load(); }}>Confirm Receipt</button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
