import React, { useEffect, useState } from 'react';
import { api, RoleWork } from '../services/api';
import type { Assignment, Sample, BootstrapData } from '../types/models';
import { useAuth } from '../hooks/useAuth';

export default function WorkList() {
  const { user } = useAuth();
  const [roleWork, setRoleWork] = useState<RoleWork>({ pending: [], inProgress: [], completed: [] });
  const [samples, setSamples] = useState<Record<string, Sample>>({});
  const [bootstrap, setBootstrap] = useState<BootstrapData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [msg, setMsg] = useState('');
  const [workerLat, setWorkerLat] = useState('');
  const [workerLon, setWorkerLon] = useState('');
  const [checkpointSample, setCheckpointSample] = useState('');
  const [checkpointContainer, setCheckpointContainer] = useState('');
  const [checkpointTemp, setCheckpointTemp] = useState('');
  const [avail, setAvail] = useState(true);
  const [presealed, setPresealed] = useState({ sampleTypeId: '', originType: 'clinic', originLat: '', originLon: '', deliveryDeadline: '', containerType: 'standard', observedTemperatureC: '20' });

  const load = async () => {
    try {
      const [rw, bt] = await Promise.all([api.listRoleWork(), api.readBootstrap()]);
      setRoleWork(rw);
      setBootstrap(bt);
      const allAssignments = [...(rw.pending || []), ...(rw.inProgress || []), ...(rw.completed || [])];
      const sampleIds = [...new Set(allAssignments.map((a) => a.sampleId).filter(Boolean))] as string[];
      if (sampleIds.length > 0) {
        const results = await Promise.all(sampleIds.map((id) => api.readSampleState(id).catch(() => null)));
        const map: Record<string, Sample> = {};
        results.forEach((s) => { if (s) map[s.sampleId] = s; });
        setSamples(map);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const accept = async (assignmentId: string) => {
    try { await api.acceptAssignment(assignmentId); setMsg('Accepted'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const decline = async (assignmentId: string) => {
    try { await api.declineAssignment(assignmentId); setMsg('Declined'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const collectSeal = async (assignmentId: string, sampleId: string) => {
    try { await api.collectAndSealSample({ assignmentId, sampleId }); setMsg('Collected & Sealed'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const recordLocation = async () => {
    try {
      await api.recordWorkerLocation(parseFloat(workerLat), parseFloat(workerLon));
      setMsg('Location recorded');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const toggleAvail = async () => {
    try { await api.setWorkerAvailability(!avail); setAvail(!avail); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const updateProgress = async (assignmentId: string, status: string) => {
    try { await api.updateAssignmentProgress({ assignmentId, status }); setMsg('Progress updated'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const recordCheckpoint = async () => {
    if (!checkpointSample) return;
    try {
      await api.recordHandlingCheckpoint({
        sampleId: checkpointSample,
        containerType: checkpointContainer,
        observedTemperatureC: checkpointTemp ? parseFloat(checkpointTemp) : undefined,
      });
      setMsg('Checkpoint recorded');
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const ingestPresealed = async () => {
    try {
      await api.ingestPresealedSample({
        sampleTypeId: presealed.sampleTypeId,
        originType: presealed.originType,
        origin: { latitude: parseFloat(presealed.originLat), longitude: parseFloat(presealed.originLon) },
        containerType: presealed.containerType,
        observedTemperatureC: parseFloat(presealed.observedTemperatureC) || 20,
        deliveryDeadline: presealed.deliveryDeadline,
      });
      setMsg('Pre-sealed sample registered');
      setPresealed({ sampleTypeId: '', originType: 'clinic', originLat: '', originLon: '', deliveryDeadline: '', containerType: 'standard', observedTemperatureC: '20' });
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  if (loading) return <div className="loading">Loading work...</div>;

  const isCCP = user?.activeRole === 'certified_collection_professional';
  const isCourier = user?.activeRole === 'relay_courier';
  const isHandler = user?.activeRole === 'node_handler';
  const isLabOp = user?.activeRole === 'laboratory_intake_operator';

  const allAssignments = [...roleWork.pending, ...roleWork.inProgress, ...roleWork.completed];

  return (
    <div>
      <h1 className="page-title">My Work</h1>
      {error && <div className="error-msg">{error}</div>}
      {msg && <div className="success-msg">{msg}</div>}

      <div className="grid grid-2" style={{ marginBottom: '1rem' }}>
        <div className="card">
          <h3>My Location</h3>
          <div className="grid grid-2">
            <div className="form-group">
              <label>Latitude</label>
              <input type="number" step="any" value={workerLat} onChange={(e) => setWorkerLat(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Longitude</label>
              <input type="number" step="any" value={workerLon} onChange={(e) => setWorkerLon(e.target.value)} />
            </div>
          </div>
          <button className="btn btn-primary" onClick={recordLocation}>Record Location</button>
        </div>

        <div className="card">
          <h3>Availability</h3>
          <button className={`btn ${avail ? 'btn-success' : 'btn-danger'}`} onClick={toggleAvail}>
            {avail ? 'Available' : 'Unavailable'}
          </button>
        </div>
      </div>

      {(isCCP || isCourier || isHandler || isLabOp) && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h3>Record Handling Checkpoint</h3>
          <div className="grid grid-3">
            <div className="form-group">
              <label>Sample ID</label>
              <input value={checkpointSample} onChange={(e) => setCheckpointSample(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Container Type</label>
              <input value={checkpointContainer} onChange={(e) => setCheckpointContainer(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Temperature (°C)</label>
              <input type="number" step="any" value={checkpointTemp} onChange={(e) => setCheckpointTemp(e.target.value)} />
            </div>
          </div>
          <button className="btn btn-primary" onClick={recordCheckpoint}>Record Checkpoint</button>
        </div>
      )}

      {(isCCP || isCourier || isHandler || isLabOp) && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h3>Ingest Pre-sealed Sample</h3>
          <div className="grid grid-2">
            <div className="form-group">
              <label>Origin Type</label>
              <select value={presealed.originType} onChange={(e) => setPresealed({ ...presealed, originType: e.target.value })}>
                <option value="clinic">Clinic</option>
                <option value="node">Collection Node</option>
              </select>
            </div>
            <div className="form-group">
              <label>Sample Type</label>
              <select value={presealed.sampleTypeId} onChange={(e) => setPresealed({ ...presealed, sampleTypeId: e.target.value })}>
                <option value="">-- Select --</option>
                {bootstrap?.lookups?.sampleTypes?.map((st) => (
                  <option key={st.sampleTypeId} value={st.sampleTypeId}>{st.name}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label>Latitude</label>
              <input type="number" step="any" value={presealed.originLat} onChange={(e) => setPresealed({ ...presealed, originLat: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Longitude</label>
              <input type="number" step="any" value={presealed.originLon} onChange={(e) => setPresealed({ ...presealed, originLon: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Container Type</label>
              <input value={presealed.containerType} onChange={(e) => setPresealed({ ...presealed, containerType: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Temperature (°C)</label>
              <input type="number" step="any" value={presealed.observedTemperatureC} onChange={(e) => setPresealed({ ...presealed, observedTemperatureC: e.target.value })} />
            </div>
            <div className="form-group">
              <label>Delivery Deadline</label>
              <input type="datetime-local" value={presealed.deliveryDeadline} onChange={(e) => setPresealed({ ...presealed, deliveryDeadline: e.target.value })} />
            </div>
          </div>
          <button className="btn btn-primary" onClick={ingestPresealed} style={{ marginTop: '0.5rem' }}>Register</button>
        </div>
      )}

      <div className="card">
        <h3>Assignments ({allAssignments.length})</h3>
        {allAssignments.length === 0 ? (
          <p style={{ color: 'var(--text-muted)', marginTop: '0.5rem' }}>No assignments</p>
        ) : (
          <table style={{ marginTop: '0.75rem' }}>
            <thead>
              <tr>
                <th>Kind</th>
                <th>Sample</th>
                <th>Action</th>
                <th>From</th>
                <th>To</th>
                <th>Status</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {allAssignments.map((a) => (
                <tr key={a.assignmentId || a.sampleId}>
                  <td>{a.kind}</td>
                  <td><code>{a.sampleId?.slice(0, 8)}</code></td>
                  <td>{a.status}</td>
                  <td>{a.fromLocationId || '-'}</td>
                  <td>{a.toLocationId || '-'}</td>
                  <td><span className={`badge badge-${a.status === 'accepted' ? 'active' : 'pending'}`}>{a.status}</span></td>
                  <td>
                    <div style={{ display: 'flex', gap: '0.25rem' }}>
                      {a.status === 'offered' && a.assignmentId && (
                        <>
                          <button className="btn btn-success" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => accept(a.assignmentId!)}>Accept</button>
                          <button className="btn btn-danger" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => decline(a.assignmentId!)}>Decline</button>
                        </>
                      )}
                      {a.status === 'accepted' && isCCP && a.kind === 'collection' && a.assignmentId && a.sampleId && (
                        <button className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => collectSeal(a.assignmentId!, a.sampleId!)}>Collect & Seal</button>
                      )}
                      {a.status === 'accepted' && (isCourier || isHandler) && a.assignmentId && (
                        <button className="btn btn-primary" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={() => updateProgress(a.assignmentId!, 'in_transit')}>Start Transit</button>
                      )}
                      {a.status === 'accepted' && isLabOp && a.kind === 'laboratory_receipt' && a.sampleId && (
                        <button className="btn btn-success" style={{ fontSize: '0.75rem', padding: '0.2rem 0.5rem' }} onClick={async () => { await api.confirmLaboratoryReceipt(a.sampleId!, user?.assignedLocationId || ''); load(); }}>Confirm Receipt</button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

