import React, { useEffect, useState, useCallback } from 'react';
import { api } from '../services/api';
import type { OperationsState, Sample, JourneyPlan } from '../types/models';

export default function OpsView() {
  const [state, setState] = useState<OperationsState | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [journeys, setJourneys] = useState<Record<string, JourneyPlan>>({});

  const load = useCallback(async () => {
    try {
      const s = await api.readOperationsState();
      setState(s);
      const jids = [...new Set(s.samples?.map((sm: Sample) => sm.active_journey_id).filter(Boolean))] as string[];
      const jmap: Record<string, JourneyPlan> = {};
      await Promise.all(jids.map(async (jid) => {
        try { jmap[jid] = await api.readJourneyPlan(jid); } catch {}
      }));
      setJourneys(jmap);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { load(); }, [load]);

  const cancelJourney = async (jid: string) => {
    try { await api.cancelJourney(jid); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const reportDisruption = async (type: string, id: string) => {
    const desc = prompt('Describe the disruption:');
    if (!desc) return;
    try { await api.reportDisruption({ element_type: type, element_id: id, description: desc }); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  if (loading) return <div className="loading">Loading operations...</div>;

  return (
    <div>
      <h1 className="page-title">Operations View</h1>
      {error && <div className="error-msg">{error}</div>}

      <div className="grid grid-3" style={{ marginBottom: '1rem' }}>
        <div className="card">
          <h3>Samples</h3>
          <p style={{ fontSize: '2rem', fontWeight: 700 }}>{state?.samples?.length ?? 0}</p>
        </div>
        <div className="card">
          <h3>Workers</h3>
          <p style={{ fontSize: '2rem', fontWeight: 700 }}>{state?.workers?.length ?? 0}</p>
        </div>
        <div className="card">
          <h3>Exceptions</h3>
          <p style={{ fontSize: '2rem', fontWeight: 700, color: state?.exceptions?.length ? 'var(--danger)' : 'inherit' }}>
            {state?.exceptions?.filter((e) => !e.resolved).length ?? 0}
          </p>
        </div>
      </div>

      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3>Workers</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>User</th><th>Role</th><th>Location</th><th>Assignment</th><th>Available</th><th></th></tr>
          </thead>
          <tbody>
            {state?.workers?.map((w) => (
              <tr key={w.user_id}>
                <td>{w.username}</td>
                <td>{w.role?.replace(/_/g, ' ')}</td>
                <td>{w.current_location ? `${w.current_location.latitude.toFixed(4)}, ${w.current_location.longitude.toFixed(4)}` : '-'}</td>
                <td>{w.active_assignment_id ? <code>{w.active_assignment_id.slice(0, 8)}</code> : '-'}</td>
                <td>{w.availability}</td>
                <td><button className="btn" style={{ fontSize: '0.75rem' }} onClick={() => reportDisruption('worker', w.user_id)}>Report Issue</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3>Samples</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>ID</th><th>Type</th><th>Status</th><th>Holder</th><th>Location Stale</th><th>Deadline</th><th></th></tr>
          </thead>
          <tbody>
            {state?.samples?.map((s) => (
              <tr key={s.id}>
                <td><code>{s.id?.slice(0, 8)}</code></td>
                <td>{s.sample_type_name || s.sample_type_id}</td>
                <td><span className={`badge badge-${s.status === 'collected' ? 'active' : 'pending'}`}>{s.status}</span></td>
                <td>{s.current_holder_name || '-'}</td>
                <td>{s.location_stale ? <span className="badge badge-inactive">Stale</span> : 'OK'}</td>
                <td>{s.delivery_deadline ? new Date(s.delivery_deadline).toLocaleString() : '-'}</td>
                <td>
                  {s.active_journey_id && (
                    <button className="btn btn-danger" style={{ fontSize: '0.75rem' }} onClick={() => cancelJourney(s.active_journey_id!)}>Cancel</button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card" style={{ marginBottom: '1rem' }}>
        <h3>Journeys</h3>
        {Object.entries(journeys).map(([jid, jp]) => (
          <div key={jid} style={{ marginBottom: '0.75rem', padding: '0.75rem', border: '1px solid var(--border)', borderRadius: 'var(--radius)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <strong><code>{jid.slice(0, 8)}</code> - {jp.status}</strong>
              <div style={{ display: 'flex', gap: '0.25rem' }}>
                <button className="btn" style={{ fontSize: '0.75rem' }} onClick={() => cancelJourney(jid)}>Cancel</button>
                <button className="btn" style={{ fontSize: '0.75rem' }} onClick={() => reportDisruption('journey', jid)}>Disruption</button>
              </div>
            </div>
            <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
              {jp.stops?.length ?? 0} stops
            </div>
          </div>
        ))}
        {Object.keys(journeys).length === 0 && <p style={{ color: 'var(--text-muted)' }}>No active journeys</p>}
      </div>

      <div className="card">
        <h3>Locations</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>Name</th><th>Functions</th><th>Active</th><th></th></tr>
          </thead>
          <tbody>
            {state?.locations?.map((loc) => (
              <tr key={loc.id}>
                <td>{loc.name}</td>
                <td>{loc.functions?.join(', ')}</td>
                <td>{loc.active ? <span className="badge badge-active">Active</span> : <span className="badge badge-inactive">Inactive</span>}</td>
                <td><button className="btn" style={{ fontSize: '0.75rem' }} onClick={() => reportDisruption('location', loc.id)}>Report Issue</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

