import React, { useEffect, useState } from 'react';
import { api } from '../services/api';
import type { User } from '../types/models';

export default function AdminUsers() {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [msg, setMsg] = useState('');

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [roles, setRoles] = useState<string[]>([]);
  const [nodeId, setNodeId] = useState('');
  const [labId, setLabId] = useState('');
  const [certs, setCerts] = useState('');

  const load = () => {
    api.readOperationsState()
      .then((s) => {
        const u = s.workers?.map((w) => ({
          id: w.user_id,
          username: w.username,
          roles: [w.role],
          active_role: w.role,
        })) as User[];
        setUsers(u);
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed'))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  const createUser = async () => {
    try {
      await api.createUser({
        username,
        password,
        roles,
        assigned_node_id: nodeId || undefined,
        assigned_laboratory_id: labId || undefined,
        certifications: certs ? certs.split(',').map((s) => s.trim()) : undefined,
      });
      setMsg('User created');
      setUsername(''); setPassword(''); setRoles([]); setNodeId(''); setLabId(''); setCerts('');
      load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const toggleRole = (r: string) => {
    setRoles((prev) => prev.includes(r) ? prev.filter((x) => x !== r) : [...prev, r]);
  };

  const deactivateUser = async (userId: string) => {
    try { await api.updateUserAccess(userId, { active: false }); setMsg('User deactivated'); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div>
      <h1 className="page-title">Manage Users</h1>
      {error && <div className="error-msg">{error}</div>}
      {msg && <div className="success-msg">{msg}</div>}

      <div className="card" style={{ marginBottom: '1rem', maxWidth: 600 }}>
        <h3>Create User</h3>
        <div className="grid grid-2">
          <div className="form-group">
            <label>Username</label>
            <input value={username} onChange={(e) => setUsername(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Password</label>
            <input type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
          </div>
        </div>
        <div className="form-group">
          <label>Roles</label>
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            {['requester', 'certified_collection_professional', 'relay_courier', 'node_handler', 'laboratory_intake_operator', 'dispatcher', 'administrator'].map((r) => (
              <button key={r} type="button" className={`role-chip${roles.includes(r) ? ' active' : ''}`} onClick={() => toggleRole(r)}>
                {r.replace(/_/g, ' ')}
              </button>
            ))}
          </div>
        </div>
        <div className="grid grid-2">
          <div className="form-group">
            <label>Assigned Node ID (optional)</label>
            <input value={nodeId} onChange={(e) => setNodeId(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Assigned Lab ID (optional)</label>
            <input value={labId} onChange={(e) => setLabId(e.target.value)} />
          </div>
        </div>
        <div className="form-group">
          <label>Certifications (comma-separated)</label>
          <input value={certs} onChange={(e) => setCerts(e.target.value)} placeholder="Amber, Indigo, Frost, Pulse" />
        </div>
        <button className="btn btn-primary" onClick={createUser}>Create User</button>
      </div>

      <div className="card">
        <h3>Users ({users.length})</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>Username</th><th>Roles</th><th>Actions</th></tr>
          </thead>
          <tbody>
            {users.map((u) => (
              <tr key={u.id}>
                <td>{u.username}</td>
                <td>{u.roles?.join(', ')}</td>
                <td>
                  <button className="btn btn-danger" style={{ fontSize: '0.75rem' }} onClick={() => deactivateUser(u.id)}>Deactivate</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

