import React, { useEffect, useState } from 'react';
import { api } from '../services/api';
import type { Location, BootstrapData } from '../types/models';

export default function AdminLocations() {
  const [locations, setLocations] = useState<Location[]>([]);
  const [bootstrap, setBootstrap] = useState<BootstrapData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [msg, setMsg] = useState('');

  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [lat, setLat] = useState('');
  const [lon, setLon] = useState('');
  const [functions, setFunctions] = useState<string[]>([]);
  const [regCap, setRegCap] = useState('100');
  const [coolCap, setCoolCap] = useState('50');

  const load = async () => {
    try {
      const [ops, bt] = await Promise.all([api.readOperationsState(), api.readBootstrap()]);
      setLocations(ops.locations || []);
      setBootstrap(bt);
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); } finally { setLoading(false); }
  };

  useEffect(() => { load(); }, []);

  const toggleFunc = (f: string) => {
    setFunctions((prev) => prev.includes(f) ? prev.filter((x) => x !== f) : [...prev, f]);
  };

  const createLocation = async () => {
    try {
      await api.createLocation({
        name,
        address,
        latitude: parseFloat(lat),
        longitude: parseFloat(lon),
        functions,
        regular_capacity: parseInt(regCap),
        cooled_capacity: parseInt(coolCap),
      });
      setMsg('Location created'); load();
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const toggleActive = async (loc: Location) => {
    try { await api.setLocationStatus(loc.id, !loc.active); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  const toggleFuncStatus = async (loc: Location, func: string, active: boolean) => {
    try { await api.setLocationFunctionStatus(loc.id, func, !active); load(); } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
  };

  if (loading) return <div className="loading">Loading...</div>;

  return (
    <div>
      <h1 className="page-title">Manage Locations</h1>
      {error && <div className="error-msg">{error}</div>}
      {msg && <div className="success-msg">{msg}</div>}

      <div className="card" style={{ marginBottom: '1rem', maxWidth: 600 }}>
        <h3>Create Location</h3>
        <div className="grid grid-2">
          <div className="form-group">
            <label>Name</label>
            <input value={name} onChange={(e) => setName(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Address</label>
            <input value={address} onChange={(e) => setAddress(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Latitude</label>
            <input type="number" step="any" value={lat} onChange={(e) => setLat(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Longitude</label>
            <input type="number" step="any" value={lon} onChange={(e) => setLon(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Regular Capacity</label>
            <input type="number" value={regCap} onChange={(e) => setRegCap(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Cooled Capacity</label>
            <input type="number" value={coolCap} onChange={(e) => setCoolCap(e.target.value)} />
          </div>
        </div>
        <div className="form-group">
          <label>Functions</label>
          <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
            {['collection_point', 'transfer_point', 'hub', 'laboratory'].map((f) => (
              <button key={f} type="button" className={`role-chip${functions.includes(f) ? ' active' : ''}`} onClick={() => toggleFunc(f)}>
                {f.replace(/_/g, ' ')}
              </button>
            ))}
          </div>
        </div>
        <button className="btn btn-primary" onClick={createLocation}>Create Location</button>
      </div>

      <div className="card">
        <h3>Locations ({locations.length})</h3>
        <table style={{ marginTop: '0.75rem' }}>
          <thead>
            <tr><th>Name</th><th>Address</th><th>Functions</th><th>Active</th><th>Capacity (R/C)</th><th>Actions</th></tr>
          </thead>
          <tbody>
            {locations.map((loc) => (
              <tr key={loc.id}>
                <td>{loc.name}</td>
                <td>{loc.address}</td>
                <td>
                  {loc.functions?.map((f) => (
                    <span key={f} style={{ display: 'inline-block', marginRight: '0.25rem' }}>
                      <span className={`badge ${loc.function_status?.[f] !== false ? 'badge-active' : 'badge-inactive'}`}
                        style={{ cursor: 'pointer' }}
                        onClick={() => toggleFuncStatus(loc, f, loc.function_status?.[f] !== false)}>
                        {f.replace(/_/g, ' ')}
                      </span>
                    </span>
                  ))}
                </td>
                <td>
                  <span className={`badge ${loc.active ? 'badge-active' : 'badge-inactive'}`} style={{ cursor: 'pointer' }} onClick={() => toggleActive(loc)}>
                    {loc.active ? 'Active' : 'Inactive'}
                  </span>
                </td>
                <td>{loc.regular_capacity} / {loc.cooled_capacity}</td>
                <td>
                  <button className="btn" style={{ fontSize: '0.75rem' }} onClick={async () => {
                    const newReg = prompt('Regular capacity:', String(loc.regular_capacity));
                    const newCool = prompt('Cooled capacity:', String(loc.cooled_capacity));
                    if (newReg || newCool) {
                      await api.configureCapacity({ entity_type: 'location', entity_id: loc.id, regular_capacity: newReg ? parseInt(newReg) : undefined, cooled_capacity: newCool ? parseInt(newCool) : undefined });
                      load();
                    }
                  }}>Edit Capacity</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

