     1	import React, { createContext, useContext, useState, useCallback, useEffect } from 'react';
     2	import type { User } from '../types/models';
     3	import { api } from '../services/api';
     4	
     5	interface AuthCtx {
     6	  user: User | null;
     7	  token: string | null;
     8	  login: (username: string, password: string) => Promise<void>;
     9	  logout: () => void;
    10	  selectRole: (role: string) => Promise<void>;
    11	  loading: boolean;
    12	}
    13	
    14	const AuthContext = createContext<AuthCtx>(null!);
    15	
    16	export function AuthProvider({ children }: { children: React.ReactNode }) {
    17	  const [user, setUser] = useState<User | null>(null);
    18	  const [token, setToken] = useState<string | null>(() => localStorage.getItem('token'));
    19	  const [loading, setLoading] = useState(true);
    20	
    21	  useEffect(() => {
    22	    const storedUserId = localStorage.getItem('userId');
    23	    if (token && storedUserId) {
    24	      api.readUser(storedUserId)
    25	        .then(setUser)
    26	        .catch(() => { localStorage.removeItem('token'); localStorage.removeItem('userId'); setToken(null); })
    27	        .finally(() => setLoading(false));
    28	    } else {
    29	      setLoading(false);
    30	    }
    31	  }, [token]);
    32	
    33	  const login = useCallback(async (username: string, password: string) => {
    34	    const res = await api.login(username, password);
    35	    localStorage.setItem('token', res.sessionToken);
    36	    localStorage.setItem('userId', res.userId);
    37	    setToken(res.sessionToken);
    38	    setUser({
    39	      userId: res.userId,
    40	      username: res.username,
    41	      roles: res.roles,
    42	      activeRole: res.roles[0],
    43	    });
    44	  }, []);
    45	
    46	  const logout = useCallback(() => {
    47	    localStorage.removeItem('token');
    48	    localStorage.removeItem('userId');
    49	    setToken(null);
    50	    setUser(null);
    51	  }, []);
    52	
    53	  const selectRole = useCallback(async (role: string) => {
    54	    const u = await api.selectRole(role);
    55	    setUser(prev => prev ? { ...prev, activeRole: u.activeRole } : null);
    56	  }, []);
    57	
    58	  return (
    59	    <AuthContext.Provider value={{ user, token, login, logout, selectRole, loading }}>
    60	      {children}
    61	    </AuthContext.Provider>
    62	  );
    63	}
    64	
    65	export function useAuth() {
    66	  return useContext(AuthContext);
    67	}

